window.SAGE_CHAPTERS = (window.SAGE_CHAPTERS || []).concat([
{
 id: "jb-1", sage: "jadabharata", n: 1, order: 5501, date: "2026-11-28",
 title: "Ṛṣabha's Eldest Son", titleTe: "ఋషభుని పెద్ద కొడుకు",
 src: "Bhāgavata 5.1–5.6 · Viṣṇu Purāṇa 2.1",
 who: ["jadabharata", "rishabha", "nabhi", "merudevi", "jayanti_r", "svayambhuva", "priyavrata", "agnidhra", "indra", "vishnu", "navayogendras", "shuka", "parikshit"],
 pages: [
  [
   ["p", "This is the story of one man who lived three lives. In the first he was a great emperor, {jadabharata|Bharata}. In the second he was a deer. In the third he was a brāhmaṇa so quiet and slow that everyone called him *jaḍa* — “dull, senseless, like a block of wood.” That is how he came to be remembered as {jadabharata|Jaḍabharata}, “Bharata the Dull.” Yet the man the world called dull was one of the wisest teachers the Purāṇas know.", "ఇది మూడు జీవితాలు గడిపిన ఒక మనిషి కథ. మొదటి జన్మలో ఆయన గొప్ప చక్రవర్తి — {jadabharata|భరతుడు}. రెండవ జన్మలో ఒక లేడి. మూడవ జన్మలో ఎంత మౌనంగా, ఎంత మందంగా ఉండేవాడంటే అందరూ ఆయనను *జడుడు* — “మొద్దు, తెలివిలేనివాడు, కట్టెముక్కలాంటివాడు” — అని పిలిచేవారు. అందుకే ఆయనను {jadabharata|జడభరతుడు} అని గుర్తుంచుకుంటాం. కానీ లోకం మొద్దు అన్న ఆ మనిషి పురాణాలు చెప్పే గొప్ప జ్ఞానులలో ఒకడు."],
   ["p", "His story is told most fully in the fifth book of the Bhāgavata Purāṇa, where the sage {shuka|Śuka} tells it to King {parikshit|Parīkṣit}, and more briefly in the second book of the Viṣṇu Purāṇa. To understand him we must begin with his family — the very first family of kings.", "ఈ కథను పూర్తిగా చెప్పేది భాగవత పురాణం ఐదవ స్కంధం; అక్కడ {shuka|శుక మహర్షి} {parikshit|పరీక్షిత్తు} మహారాజుకు చెబుతాడు. విష్ణు పురాణం రెండవ అంశంలో కూడా క్లుప్తంగా ఉంది. ఆయనను అర్థం చేసుకోవాలంటే ఆయన వంశంతో మొదలుపెట్టాలి — అది లోకంలో మొట్టమొదటి రాజవంశం."],
   ["h", "From Manu to Nābhi", "మనువు నుండి నాభి వరకు"],
   ["p", "The first Manu, {svayambhuva|Svāyambhuva Manu}, had a son named {priyavrata|Priyavrata}, a mighty king. Priyavrata's son {agnidhra|Āgnīdhra} ruled Jambūdvīpa, the island-continent on which we live, and divided it among his nine sons. The eldest of them, {nabhi|Nābhi}, received the southern land, which was then called *Ajanābha* after him.", "మొదటి మనువు {svayambhuva|స్వాయంభువ మనువుకు} {priyavrata|ప్రియవ్రతుడు} అనే మహాబలుడైన కొడుకు ఉన్నాడు. ప్రియవ్రతుని కొడుకు {agnidhra|ఆగ్నీధ్రుడు} మనం ఉండే జంబూద్వీపాన్ని ఏలి, దాన్ని తన తొమ్మిది మంది కొడుకులకు పంచి ఇచ్చాడు. వాళ్ళలో పెద్దవాడు {nabhi|నాభికి} దక్షిణాన ఉన్న భూభాగం వచ్చింది; ఆయన పేరు మీదుగా దానిని అప్పుడు *అజనాభం* అని పిలిచేవారు."]
  ],
  [
   ["h", "A son like the Lord", "భగవంతుని లాంటి కొడుకు"],
   ["p", "Nābhi and his queen {merudevi|Merudevī} had no child. They performed a great sacrifice, and the Bhāgavata says that {vishnu|Viṣṇu} himself appeared in the fire, shining and four-armed. The priests prayed: “Give this king a son like you.” The Lord smiled: “There is no one like me. So I myself will be born as his son.” The child born to Merudevī was named {rishabha|Ṛṣabha}, “the best, the strongest.”", "నాభికీ ఆయన రాణి {merudevi|మేరుదేవికీ} సంతానం లేదు. వాళ్ళు ఒక గొప్ప యజ్ఞం చేశారు. అప్పుడు {vishnu|విష్ణువే} స్వయంగా నాలుగు చేతులతో, తేజస్సుతో యజ్ఞకుండంలో ప్రత్యక్షమయ్యాడని భాగవతం చెబుతుంది. ఋత్విక్కులు “ఈ రాజుకు నీ లాంటి కొడుకును ప్రసాదించు” అని ప్రార్థించారు. స్వామి నవ్వి, “నా లాంటివాడు ఇంకొకడు లేడు. కాబట్టి నేనే ఆయన కొడుకుగా పుడతాను” అన్నాడు. మేరుదేవికి పుట్టిన బిడ్డకు {rishabha|ఋషభుడు} — “శ్రేష్ఠుడు, బలశాలి” — అని పేరు పెట్టారు."],
   ["p", "Ṛṣabha grew up strong, calm and kind, and the people loved him. Once {indra|Indra}, jealous of his greatness, held back the rain from his land; Ṛṣabha only smiled and, by his own yoga-power, made rain fall on Ajanābha. Indra, ashamed and won over, gave him his own daughter {jayanti_r|Jayantī} as a wife. Ṛṣabha and Jayantī had a hundred sons. The eldest, and the best in every virtue, was {jadabharata|Bharata}.", "ఋషభుడు బలంగా, ప్రశాంతంగా, దయగా పెరిగాడు; ప్రజలు ఆయనను ప్రాణంగా ప్రేమించారు. ఒకసారి ఆయన గొప్పతనం చూసి ఓర్వలేక {indra|ఇంద్రుడు} ఆ దేశం మీద వర్షం కురవకుండా ఆపాడు. ఋషభుడు చిరునవ్వు నవ్వి, తన యోగశక్తితో అజనాభం మీద వర్షం కురిపించాడు. ఇంద్రుడు సిగ్గుపడి, మనసు మార్చుకుని, తన కూతురు {jayanti_r|జయంతిని} ఆయనకు ఇచ్చి పెళ్ళి చేశాడు. ఋషభునికీ జయంతికీ వంద మంది కొడుకులు పుట్టారు. వాళ్ళలో పెద్దవాడు, అన్ని గుణాలలోనూ శ్రేష్ఠుడు — {jadabharata|భరతుడు}."],
   ["p", "Of the other ninety-nine, the Bhāgavata says, nine became kings of the regions around; nine — the {navayogendras|nine Yogendras} — became wandering sages, who would one day teach King Nimi of Videha; and the remaining eighty-one became learned brāhmaṇas devoted to Vedic rites. So Bharata grew up among brothers who were kings, sages and priests.", "మిగిలిన తొంభై తొమ్మిది మందిలో తొమ్మిది మంది చుట్టుపక్కల దేశాలకు రాజులయ్యారు; ఇంకో తొమ్మిది మంది — {navayogendras|నవ యోగీంద్రులు} — సంచరించే మునులయ్యారు; వాళ్ళే తరువాత విదేహ రాజు నిమికి బోధించారు; మిగిలిన ఎనభై ఒక్క మంది వైదిక కర్మలలో నిష్ఠ ఉన్న పండితులైన బ్రాహ్మణులయ్యారని భాగవతం చెబుతుంది. అంటే భరతుడు రాజులూ మునులూ పండితులూ అయిన అన్నదమ్ముల మధ్య పెరిగాడు."]
  ],
  [
   ["h", "A father's last lesson", "తండ్రి చివరి పాఠం"],
   ["p", "When the time came for Ṛṣabha to leave the world, he called his sons together at Brahmāvarta, with sages listening, and spoke to them. His teaching begins with a verse that Bharata would one day live out in his own three lives:", "లోకాన్ని వదిలి వెళ్ళే సమయం వచ్చినప్పుడు ఋషభుడు బ్రహ్మావర్తంలో మునులు వింటూ ఉండగా కొడుకులందరినీ పిలిచి ఉపదేశించాడు. ఆ ఉపదేశం ఒక శ్లోకంతో మొదలవుతుంది — భరతుడు తన మూడు జన్మలలో దాన్నే అనుభవించి చూపించాడు:"],
   ["sloka", ["నాయం దేహో దేహభాజాం నృలోకే కష్టాన్ కామానర్హతే విడ్భుజాం యే ।", "తపో దివ్యం పుత్రకా యేన సత్త్వం శుద్ధ్యేద్యస్మాద్బ్రహ్మసౌఖ్యం త్వనంతమ్ ॥"], ["nāyaṃ deho deha-bhājāṃ nṛloke kaṣṭān kāmān arhate viḍ-bhujāṃ ye |", "tapo divyaṃ putrakā yena sattvaṃ śuddhyed yasmād brahma-saukhyaṃ tv anantam ||"], "“My sons, this human body is not meant for hard-won pleasures that even creatures living on filth can have. It is meant for divine tapas, by which the heart is made pure — and from that comes the endless joy of Brahman.” (Bhāgavata 5.5.1)", "“నాయనలారా! ఈ మనుష్య దేహం కష్టపడి సంపాదించే సుఖాల కోసం కాదు — ఆ సుఖాలు మలం తినే జంతువులకు కూడా దొరుకుతాయి. ఇది దివ్యమైన తపస్సు కోసం; దానితో మనసు శుద్ధి అవుతుంది; దాని నుండే అంతులేని బ్రహ్మానందం కలుగుతుంది.” (భాగవతం 5.5.1)"],
   ["p", "Then Ṛṣabha placed Bharata on the throne, laid aside everything — even his clothes — and walked out of the kingdom. He wandered like a madman, deaf and silent, letting people mock him and throw dirt at him, never answering. The Bhāgavata says he roamed at last in the south, in the lands of Koṅka, Veṅka and Kuṭaka, with a stone in his mouth so as not to speak; there a forest fire, sparked when bamboos rubbed together in the wind, swept the forest and his body with it. The Viṣṇu Purāṇa tells it more simply: Ṛṣabha crowned Bharata, went to the hermitage of {pulaha|Pulaha} for tapas, and from there set out on his last journey.", "తరువాత ఋషభుడు భరతునికి పట్టాభిషేకం చేసి, అన్నీ వదిలేశాడు — ఒంటి మీది బట్టలు కూడా — రాజ్యం దాటి వెళ్ళిపోయాడు. పిచ్చివాడిలా, చెవిటివాడిలా, మూగవాడిలా తిరిగాడు; జనం ఎగతాళి చేసినా, మట్టి విసిరినా జవాబు చెప్పలేదు. చివరికి దక్షిణాన కొంక, వేంక, కుటక దేశాలలో, మాట్లాడకుండా నోట్లో ఒక రాయి పెట్టుకుని తిరిగాడని, అక్కడ గాలికి వెదుళ్ళు ఒరుసుకుని పుట్టిన కార్చిచ్చు ఆ అడవినీ ఆయన దేహాన్నీ దహించిందని భాగవతం చెబుతుంది. విష్ణు పురాణం సరళంగా చెబుతుంది: ఋషభుడు భరతునికి పట్టం కట్టి, తపస్సు కోసం {pulaha|పులహుని} ఆశ్రమానికి వెళ్ళి, అక్కడి నుండి చివరి ప్రయాణానికి బయలుదేరాడు."],
   ["dyk", "🕉️", "Jains honour Ṛṣabha as Ṛṣabhanātha (Ādinātha), the first of their twenty-four Tīrthaṅkaras, and they too remember his son Bharata as the first great emperor. One father and son are revered in two traditions.", "జైనులు ఋషభుని తమ ఇరవై నలుగురు తీర్థంకరులలో మొదటివాడైన ఋషభనాథునిగా (ఆదినాథునిగా) పూజిస్తారు; ఆయన కొడుకు భరతుని మొదటి చక్రవర్తిగా వాళ్ళు కూడా గుర్తుంచుకుంటారు. ఒకే తండ్రీ కొడుకులు రెండు సంప్రదాయాలలో పూజ్యులు."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapters 1–6: Priyavrata and Āgnīdhra; Nābhi and Merudevī's sacrifice and Ṛṣabha's birth; Indra's rain withheld; Jayantī and the hundred sons; Ṛṣabha's teaching at Brahmāvarta (5.5.1 quoted); his life as an avadhūta and his end in the southern forest. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 1: Nābhi, Ṛṣabha, Bharata, and Ṛṣabha's going to Pulaha's hermitage.", "భాగవత పురాణం, ఐదవ స్కంధం, 1–6 అధ్యాయాలు: ప్రియవ్రతుడు, ఆగ్నీధ్రుడు; నాభి మేరుదేవిల యజ్ఞం, ఋషభుని జననం; ఇంద్రుడు వర్షం ఆపడం; జయంతి, వంద మంది కొడుకులు; బ్రహ్మావర్తంలో ఋషభుని ఉపదేశం (5.5.1 ఉదహరించాం); ఆయన అవధూత జీవితం, దక్షిణారణ్యంలో అంతం. విష్ణు పురాణం, రెండవ అంశం, 1వ అధ్యాయం: నాభి, ఋషభుడు, భరతుడు; ఋషభుడు పులహాశ్రమానికి వెళ్ళడం."]
  ]
 ],
 remember: [
  ["{jadabharata|Bharata} was the eldest of {rishabha|Ṛṣabha's} hundred sons, in the line of Svāyambhuva Manu.", "{jadabharata|భరతుడు} స్వాయంభువ మనువు వంశంలో {rishabha|ఋషభుని} వంద మంది కొడుకులలో పెద్దవాడు."],
  ["Ṛṣabha taught that the human body is for tapas and inner purity, not for pleasures any animal can have.", "మనిషి దేహం ఏ జంతువుకైనా దొరికే సుఖాల కోసం కాదు, తపస్సు కోసం, మనశ్శుద్ధి కోసం అని ఋషభుడు బోధించాడు."],
  ["Ṛṣabha crowned Bharata and left the world as a silent wandering sage.", "ఋషభుడు భరతునికి పట్టం కట్టి, మౌనంగా తిరిగే అవధూతగా లోకాన్ని వదిలి వెళ్ళాడు."]
 ],
 think: ["Ṛṣabha gave up a kingdom and let people mock him without answering. What do you think it takes to be insulted and stay calm?", "ఋషభుడు రాజ్యం వదిలి, జనం ఎగతాళి చేసినా జవాబు చెప్పలేదు. అవమానం జరిగినా ప్రశాంతంగా ఉండాలంటే మనిషికి ఏం కావాలని మీరు అనుకుంటున్నారు?"]
},
{
 id: "jb-2", sage: "jadabharata", n: 2, order: 5502, date: "2026-11-28",
 title: "The King Whose Name the Land Took", titleTe: "దేశానికి తన పేరిచ్చిన రాజు",
 src: "Bhāgavata 5.4, 5.7 · Viṣṇu Purāṇa 2.1 · Mahābhārata, Ādi Parva",
 who: ["jadabharata", "panchajani", "sumati_b", "rishabha", "vishnu", "dushyanta", "shakuntala"],
 pages: [
  [
   ["p", "{jadabharata|Bharata} ruled as his father had taught him. The Bhāgavata says he married {panchajani|Pañcajanī}, daughter of Viśvarūpa, and had five sons — {sumati_b|Sumati}, Rāṣṭrabhṛt, Sudarśana, Āvaraṇa and Dhūmraketu. He cared for his people the way a father cares for children, and kept to his own duties without pride.", "{jadabharata|భరతుడు} తండ్రి నేర్పినట్లే పాలించాడు. విశ్వరూపుని కూతురు {panchajani|పంచజనిని} పెళ్ళాడి, {sumati_b|సుమతి}, రాష్ట్రభృత్తు, సుదర్శనుడు, ఆవరణుడు, ధూమ్రకేతువు అనే ఐదుగురు కొడుకులను కన్నాడని భాగవతం చెబుతుంది. తండ్రి పిల్లలను చూసుకున్నట్టు ప్రజలను చూసుకున్నాడు; గర్వం లేకుండా తన ధర్మం తాను చేసుకుపోయాడు."],
   ["p", "He performed many great Vedic sacrifices, large and small, each in its proper season. But the Bhāgavata notices something about the way he did them: he did not do them for the merit they would bring. As each offering went into the fire, he silently gave its fruit to {vishnu|Vāsudeva}, the Lord within all the gods, and thought, “The gods who receive this are only His limbs.” His rituals made his heart purer every year, and his love for the Lord grew quietly within him.", "ఆయన చిన్నా పెద్దా ఎన్నో వైదిక యజ్ఞాలు, ఒక్కొక్కటీ దాని కాలంలో చేశాడు. కానీ ఆయన చేసిన తీరును భాగవతం ప్రత్యేకంగా చెబుతుంది: వాటి వల్ల వచ్చే పుణ్యం కోసం ఆయన చేయలేదు. ప్రతి ఆహుతి అగ్నిలో పడుతుంటే, దాని ఫలాన్ని మనసులోనే దేవతలందరిలోనూ ఉండే {vishnu|వాసుదేవునికి} అర్పించేవాడు — “దీన్ని అందుకునే దేవతలు ఆయన అవయవాలే” అనుకునేవాడు. ఏటేటా ఆ కర్మలు ఆయన మనసును ఇంకా శుద్ధి చేశాయి; భగవంతుని మీద ప్రేమ లోలోపల నిశ్శబ్దంగా పెరిగింది."]
  ],
  [
   ["h", "“From him this land is Bhārata”", "“ఆయన వల్లే ఈ దేశం భారతం”"],
   ["p", "Here the Purāṇas make a large claim. The land that had been called Ajanābha after his grandfather Nābhi, they say, came to be called *Bhārata-varṣa* — the land of Bharata — after this king. The Bhāgavata says so in the chapters on Ṛṣabha and Bharata, and the Viṣṇu Purāṇa says the same in its account of the earth: Ṛṣabha's son Bharata ruled it, and from him it took its name.", "ఇక్కడ పురాణాలు ఒక పెద్ద మాట చెబుతాయి. తాత నాభి పేరు మీదుగా అజనాభం అని పిలవబడిన దేశం, ఈ రాజు పేరు మీదుగా *భారతవర్షం* — భరతుని దేశం — అని పిలవబడిందని అవి చెబుతాయి. ఋషభ భరతుల కథ చెప్పే అధ్యాయాలలో భాగవతం ఇలా అంటుంది; భూమి వర్ణనలో విష్ణు పురాణం కూడా అదే చెబుతుంది: ఋషభుని కొడుకు భరతుడు ఈ దేశాన్ని ఏలాడు; ఆయన వల్లే దీనికి ఆ పేరు వచ్చింది."],
   ["more", "Another Bharata, another answer", "ఇంకో భరతుడు, ఇంకో జవాబు", "The Mahābhārata names a different king", "మహాభారతం వేరే రాజు పేరు చెబుతుంది", [
    ["p", "The Mahābhārata, in its Ādi Parva, tells the story of King {dushyanta|Duṣyanta} and {shakuntala|Śakuntalā} and their son Bharata, the great emperor of the Puru line — and says the Bhārata family and its fame come from that Bharata. Later readers have often linked the land's name to him as well. So two Bharatas are remembered as the source of the name: Ṛṣabha's son in the Bhāgavata, the Viṣṇu Purāṇa and several other Purāṇas, and Śakuntalā's son in the Mahābhārata. The texts simply give different answers, and we keep both.", "మహాభారతం ఆదిపర్వంలో {dushyanta|దుష్యంత} మహారాజు, {shakuntala|శకుంతల}, వాళ్ళ కొడుకు — పూరువంశపు చక్రవర్తి భరతుని కథ ఉంది; భరత వంశమూ దాని కీర్తీ ఆ భరతుని నుండే వచ్చాయని అది చెబుతుంది. తరువాతి కాలంలో చాలా మంది దేశం పేరును కూడా ఆయనకే ముడిపెట్టారు. అంటే ఈ పేరుకు మూలంగా ఇద్దరు భరతులను గుర్తుంచుకుంటాం: భాగవతం, విష్ణు పురాణం, ఇంకా కొన్ని పురాణాలలో ఋషభుని కొడుకు; మహాభారతంలో శకుంతల కొడుకు. గ్రంథాలు వేర్వేరు జవాబులు ఇస్తాయి; మనం రెండింటినీ గుర్తుంచుకుందాం."]
   ]],
   ["dyk", "🗺️", "When a Telugu priest begins a pūjā with the saṅkalpa “…jambūdvīpe bharata-varṣe bharata-khaṇḍe…”, he is naming the land by this old geography — Jambūdvīpa, and in it the land of Bharata.", "తెలుగు పురోహితుడు పూజ మొదట్లో సంకల్పం చెబుతూ “…జంబూద్వీపే భరతవర్షే భరతఖండే…” అన్నప్పుడు, ఈ పాత భూగోళం ప్రకారమే మనం ఉన్న చోటును చెబుతున్నాడు — జంబూద్వీపం, అందులో భరతుని దేశం."]
  ],
  [
   ["h", "Enough", "ఇక చాలు"],
   ["p", "Kings of that first age lived and ruled for an immensely long time, and the Bhāgavata says Bharata ruled for ages beyond counting. But one day he felt that he had had enough of ruling, and that the time had come for what his father had taught him. He divided his wealth fairly among his sons, handed over the kingdom, and left the palace — not angrily, not in sorrow, but the way a man gets up from a meal when he is full.", "ఆ మొదటి యుగపు రాజులు ఊహించలేనంత దీర్ఘకాలం బతికి పాలించారు; భరతుడు కూడా లెక్కలేనన్ని ఏళ్ళు ఏలాడని భాగవతం చెబుతుంది. కానీ ఒక రోజు ఇక రాజ్యం చాలు అనిపించింది; తండ్రి నేర్పిన దానికి సమయం వచ్చిందనిపించింది. సంపదను కొడుకులకు న్యాయంగా పంచి, రాజ్యం అప్పగించి, అంతఃపురం వదిలి వెళ్ళిపోయాడు — కోపంతో కాదు, దుఃఖంతో కాదు; కడుపు నిండిన మనిషి భోజనం దగ్గర నుండి లేచినట్టు."],
   ["p", "He went north, towards the mountains, to the hermitage of the sage {pulaha|Pulaha}. Remember that place — for everything that happens next, the joy and the fall, happens on the bank of its river.", "ఆయన ఉత్తరం వైపు, కొండల వైపు, {pulaha|పులహ} మహర్షి ఆశ్రమానికి వెళ్ళాడు. ఆ చోటును గుర్తుంచుకోండి — ఇకపై జరిగేదంతా, ఆనందమూ పతనమూ, ఆ నది ఒడ్డునే జరుగుతుంది."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 4 (Ajanābha called Bhārata after Bharata) and chapter 7 (Pañcajanī and the five sons; Bharata's sacrifices offered to Vāsudeva; dividing his wealth and going to Pulaha's hermitage). Viṣṇu Purāṇa, Aṃśa 2, adhyāya 1 (the land named after Ṛṣabha's son Bharata). Mahābhārata, Ādi Parva, the story of Duṣyanta, Śakuntalā and their son Bharata.", "భాగవత పురాణం, ఐదవ స్కంధం, 4వ అధ్యాయం (భరతుని పేరు మీదుగా అజనాభం భారతం అయింది), 7వ అధ్యాయం (పంచజని, ఐదుగురు కొడుకులు; వాసుదేవునికి అర్పించిన యజ్ఞాలు; సంపద పంచి పులహాశ్రమానికి వెళ్ళడం). విష్ణు పురాణం, రెండవ అంశం, 1వ అధ్యాయం (ఋషభ పుత్రుడు భరతుని పేరు దేశానికి). మహాభారతం, ఆదిపర్వం, దుష్యంత శకుంతలల కొడుకు భరతుని కథ."]
  ]
 ],
 remember: [
  ["{jadabharata|Bharata} ruled with care and offered the fruit of every sacrifice to the Lord.", "{jadabharata|భరతుడు} శ్రద్ధగా పాలించాడు; ప్రతి యజ్ఞఫలాన్నీ భగవంతునికి అర్పించాడు."],
  ["The Bhāgavata and Viṣṇu Purāṇa say Bhārata-varṣa is named after him; the Mahābhārata links the Bhārata name to Śakuntalā's son.", "భారతవర్షం ఈయన పేరు మీదే వచ్చిందని భాగవతం, విష్ణు పురాణం చెబుతాయి; భరత నామాన్ని మహాభారతం శకుంతల కొడుకుతో ముడిపెడుతుంది."],
  ["When he had had enough, he shared out his wealth and went to Pulaha's hermitage.", "ఇక చాలు అనిపించినప్పుడు సంపద పంచి పులహాశ్రమానికి వెళ్ళాడు."]
 ],
 think: ["Bharata left the throne “the way a man gets up when he is full.” How is leaving something because you are satisfied different from leaving it because you are angry or sad?", "“కడుపు నిండిన మనిషి లేచినట్టు” భరతుడు సింహాసనం వదిలాడు. తృప్తితో వదలడానికీ, కోపంతోనో బాధతోనో వదలడానికీ తేడా ఏమిటి?"]
},
{
 id: "jb-3", sage: "jadabharata", n: 3, order: 5503, date: "2026-11-28",
 title: "The Hermitage on the Gaṇḍakī", titleTe: "గండకీ తీరంలో ఆశ్రమం",
 src: "Bhāgavata 5.7 · Viṣṇu Purāṇa 2.13",
 who: ["jadabharata", "pulaha", "vishnu"],
 pages: [
  [
   ["p", "{pulaha|Pulaha's} hermitage stood at a holy place the Bhāgavata calls Hari-kṣetra, “the Lord's own field,” beside the river Gaṇḍakī — which it also calls the Cakra-nadī, “the river of discs.” The stones in its bed bear round markings, above and below, like the discus of {vishnu|Viṣṇu}. These are the *śālagrāma* stones, and to this day they are worshipped in homes as the Lord himself. The Viṣṇu Purāṇa too names the place Śālagrāma.", "{pulaha|పులహుని} ఆశ్రమం భాగవతం హరిక్షేత్రం — “స్వామి సొంత క్షేత్రం” — అని పిలిచే పుణ్యస్థలంలో, గండకీ నది ఒడ్డున ఉంది; ఆ నదినే చక్రనది — “చక్రాల నది” — అని కూడా అంటుంది. దాని అడుగున ఉండే రాళ్ళ మీద పైనా కిందా {vishnu|విష్ణువు} చక్రం లాంటి గుండ్రని గుర్తులు ఉంటాయి. అవే *సాలగ్రామాలు*; ఈ రోజుకీ ఇళ్ళలో వాటిని సాక్షాత్తు స్వామిగానే పూజిస్తారు. విష్ణు పురాణం కూడా ఆ చోటును సాలగ్రామం అనే అంటుంది."],
   ["dyk", "🪨", "The Gaṇḍakī flows down from the Himālaya through what is now Nepal; the śālagrāma stones come from its upper reaches. Many Telugu homes keep one in the pūjā room and give it tulasī every day.", "గండకీ నది హిమాలయాల నుండి ఇప్పటి నేపాల్ గుండా ప్రవహిస్తుంది; సాలగ్రామాలు దాని ఎగువ ప్రాంతం నుండి వస్తాయి. చాలా తెలుగు ఇళ్ళలో దేవుడి గదిలో సాలగ్రామం పెట్టి రోజూ తులసి వేస్తారు."]
  ],
  [
   ["h", "A king becomes a hermit", "రాజు ముని అయ్యాడు"],
   ["p", "There Bharata lived alone in a small garden of the hermitage. He bathed in the river three times a day. He wore a deerskin, and his hair grew long and matted. He gathered tender leaves, flowers, tulasī, water and the roots and fruits of the forest, and with them worshipped the Lord — not with gold and grand rites as in the palace, but with whatever the forest gave.", "అక్కడ భరతుడు ఆశ్రమంలోని ఒక చిన్న తోటలో ఒంటరిగా ఉన్నాడు. రోజుకు మూడుసార్లు నదిలో స్నానం చేసేవాడు. జింక చర్మం కట్టుకున్నాడు; జుట్టు పెరిగి జడలు కట్టింది. లేత చిగుళ్ళు, పూలు, తులసి, నీళ్ళు, అడవిలో దొరికే దుంపలు, పళ్ళు తెచ్చి వాటితో భగవంతుని పూజించేవాడు — అంతఃపురంలో లాగా బంగారంతో, ఆడంబరంతో కాదు; అడవి ఇచ్చిన దానితో."],
   ["p", "The Bhāgavata describes what happened to him inside. His mind, freed from every other desire, became quiet. Sometimes in worship his hair stood on end, tears ran down his face, and he forgot even the rite he was doing. Each morning, as the sun rose, he stood in the river and praised the Lord who shines within the sun, with an old hymn to the light beyond darkness that the Purāṇa gives in full.", "లోపల ఆయనకు ఏం జరిగిందో భాగవతం వర్ణిస్తుంది. ఇంకే కోరికా లేని ఆయన మనసు ప్రశాంతమైంది. పూజ చేస్తుండగా ఒక్కోసారి ఒళ్ళు పులకరించేది, కళ్ళ నుండి నీళ్ళు కారేవి, చేస్తున్న పూజనే మరిచిపోయేవాడు. రోజూ ఉదయం సూర్యుడు ఉదయిస్తుంటే నదిలో నిలబడి, సూర్యునిలో ప్రకాశించే స్వామిని — చీకటికి అవతల ఉన్న వెలుగును — ఒక పాత స్తోత్రంతో కీర్తించేవాడు; ఆ స్తోత్రం పురాణంలో పూర్తిగా ఉంది."]
  ],
  [
   ["p", "Here the story could have ended. A good king, a wise renunciation, a quiet hermitage, a heart full of devotion — what more could anyone want? But the Purāṇas do not tell Bharata's story because it ended well here. They tell it because of what happened next, on the bank of this same river, to a man who had already given up a whole kingdom.", "కథ ఇక్కడే ముగిసి ఉండవచ్చు. మంచి రాజు, వివేకంతో చేసిన త్యాగం, ప్రశాంతమైన ఆశ్రమం, భక్తితో నిండిన మనసు — ఇంకేం కావాలి? కానీ పురాణాలు భరతుని కథ చెప్పేది అది ఇక్కడ బాగా ముగిసిందని కాదు. ఒక రాజ్యాన్నే వదిలిన మనిషికి, ఇదే నది ఒడ్డున, తరువాత ఏం జరిగిందో చెప్పడానికే."],
   ["dyk", "🤔", "A whole kingdom, five sons, a queen and endless wealth were easy for Bharata to give up. What caught him was something much smaller. Keep that in mind as you read on.", "మొత్తం రాజ్యం, ఐదుగురు కొడుకులు, రాణి, అంతులేని సంపద — ఇవన్నీ వదలడం భరతునికి సులువైంది. ఆయనను పట్టుకున్నది ఇంకా చాలా చిన్నది. ముందుకు చదివేటప్పుడు ఇది గుర్తుంచుకోండి."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 7: Pulaha's hermitage at Hari-kṣetra on the Cakra-nadī (Gaṇḍakī), its marked stones; Bharata's worship with leaves, tulasī, water, roots and fruits; his devotion and his morning hymn to the Lord in the sun. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: Bharata at Śālagrāma.", "భాగవత పురాణం, ఐదవ స్కంధం, 7వ అధ్యాయం: చక్రనది (గండకీ) ఒడ్డున హరిక్షేత్రంలో పులహాశ్రమం, గుర్తులున్న రాళ్ళు; చిగుళ్ళు, తులసి, నీళ్ళు, దుంపలు, పళ్ళతో భరతుని పూజ; ఆయన భక్తి, సూర్యునిలోని స్వామికి ఉదయపు స్తోత్రం. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: సాలగ్రామంలో భరతుడు."]
  ]
 ],
 remember: [
  ["{jadabharata|Bharata} lived at {pulaha|Pulaha's} hermitage on the Gaṇḍakī, where the śālagrāma stones are found.", "{jadabharata|భరతుడు} సాలగ్రామాలు దొరికే గండకీ తీరంలోని {pulaha|పులహుని} ఆశ్రమంలో ఉన్నాడు."],
  ["He worshipped the Lord with leaves, flowers, tulasī and water — whatever the forest gave.", "అడవి ఇచ్చిన చిగుళ్ళు, పూలు, తులసి, నీళ్ళతో స్వామిని పూజించాడు."],
  ["His devotion grew so deep that he would forget the rite he was doing.", "చేస్తున్న పూజనే మరిచిపోయేంత గాఢమైంది ఆయన భక్తి."]
 ],
 think: ["Bharata worshipped with simple things from the forest instead of gold. Does the value of an offering depend on what it costs?", "భరతుడు బంగారం బదులు అడవిలో దొరికే సాధారణ వస్తువులతో పూజించాడు. ఒక అర్పణ విలువ దాని ఖరీదు మీద ఆధారపడుతుందా?"]
},
{
 id: "jb-4", sage: "jadabharata", n: 4, order: 5504, date: "2026-11-28",
 title: "The Fawn in the River", titleTe: "నదిలో లేడిపిల్ల",
 src: "Bhāgavata 5.8 · Viṣṇu Purāṇa 2.13",
 who: ["jadabharata", "jbfawn"],
 pages: [
  [
   ["p", "One morning {jadabharata|Bharata} bathed in the Gaṇḍakī as usual, and sat on the bank repeating the sacred syllable *Om*. A doe came down to the water to drink. She was alone, thirsty, and heavy with a fawn that was about to be born.", "ఒక రోజు ఉదయం {jadabharata|భరతుడు} ఎప్పటిలాగే గండకీలో స్నానం చేసి, ఒడ్డున కూర్చుని *ఓం* కారం జపిస్తున్నాడు. ఒక ఆడ లేడి నీళ్ళు తాగడానికి నది దగ్గరకు వచ్చింది. అది ఒంటరిగా ఉంది, దాహంతో ఉంది, పుట్టబోయే పిల్లతో నిండు గర్భంతో ఉంది."],
   ["p", "As she drank, a lion roared somewhere close by — a roar that shook the whole forest. Mad with fear, the doe leaped straight across the river. In that great leap, the fawn slipped from her womb and fell into the rushing water. The mother reached the far bank, crept into a cave in the hills, and there, worn out by fright and the leap, she died.", "అది నీళ్ళు తాగుతుండగా దగ్గరలో ఎక్కడో ఒక సింహం గర్జించింది — అడవంతా వణికిపోయే గర్జన. భయంతో వెర్రెత్తిన లేడి ఒక్క ఉదుటున నది దాటి దూకింది. ఆ పెద్ద దూకులో పిల్ల దాని గర్భం నుండి జారి ఉరకలెత్తే నీళ్ళలో పడింది. తల్లి అవతలి ఒడ్డు చేరి, కొండల్లోని ఒక గుహలోకి దూరి, భయంతోనూ ఆ దూకు శ్రమతోనూ అక్కడే ప్రాణం విడిచింది."]
  ],
  [
   ["h", "“Who else will save it?”", "“దీన్ని ఇంకెవరు కాపాడతారు?”"],
   ["p", "Bharata saw the tiny newborn fawn tumbling in the current, all alone. His heart melted. Any kind person would have done what he did: he waded in, lifted it out, carried it to his hermitage and warmed it. “Its mother is dead,” he thought. “It has no one but me.”", "నీటి ప్రవాహంలో దొర్లుతున్న, ఒంటరిదైన ఆ పసి లేడిపిల్లను భరతుడు చూశాడు. ఆయన మనసు కరిగిపోయింది. దయగల ఎవరైనా చేసేదే ఆయనా చేశాడు: నీళ్ళలోకి దిగి దాన్ని బయటకు తీసి, ఆశ్రమానికి తెచ్చి, వెచ్చదనం ఇచ్చాడు. “దీని తల్లి చచ్చిపోయింది. దీనికి నేను తప్ప ఎవరూ లేరు” అనుకున్నాడు."],
   ["p", "Notice: nothing here was wrong. To save a helpless creature is dharma. The Purāṇas never blame Bharata for pulling the fawn out of the river. The trouble came slowly, afterwards — not from the kindness, but from what the kindness grew into.", "గమనించండి: ఇందులో తప్పు ఏమీ లేదు. నిస్సహాయ ప్రాణిని కాపాడటం ధర్మమే. లేడిపిల్లను నదిలో నుండి తీసినందుకు పురాణాలు భరతుని ఎక్కడా తప్పు పట్టవు. సమస్య తరువాత నెమ్మదిగా వచ్చింది — దయ వల్ల కాదు, ఆ దయ ఏదిగా మారిందో దాని వల్ల."]
  ],
  [
   ["h", "A little deer in the hermitage", "ఆశ్రమంలో చిన్న లేడి"],
   ["p", "He fed the {jbfawn|fawn} with tender grass, guarded it from wolves and jackals, scratched its neck when it itched, and stroked it when it lay down beside him. When it skipped about the hermitage he watched it and smiled. When it slept he sat near it. Little by little, the Bhāgavata says, his daily rules of worship slipped — one day one practice, the next day another — until he was keeping almost none of them. All his care went to the deer.", "లేత గడ్డి తినిపించి, తోడేళ్ళ నుండి నక్కల నుండి కాపాడి, దురద పెడితే మెడ గోకి, పక్కన పడుకుంటే నిమురుతూ ఆ {jbfawn|లేడిపిల్లను} పెంచాడు. అది ఆశ్రమమంతా గెంతుతుంటే చూసి నవ్వుకునేవాడు. అది నిద్రపోతుంటే దగ్గరే కూర్చునేవాడు. కొద్దికొద్దిగా ఆయన నిత్యపూజా నియమాలు జారిపోయాయని భాగవతం చెబుతుంది — ఒక రోజు ఒకటి, మర్నాడు ఇంకొకటి — చివరికి దాదాపు ఏదీ మిగల్లేదు. ఆయన శ్రద్ధ అంతా ఆ లేడి మీదే."],
   ["p", "He told himself it was his duty: “It came to me for shelter. Good people do not abandon those who come to them, even at the cost of their own good.” The reason sounded noble. The Bhāgavata gently shows that it was also a door, and that through it the whole world he had left behind was walking back in.", "అది తన ధర్మమే అని తనకు తాను చెప్పుకున్నాడు: “ఇది నన్ను శరణు కోరి వచ్చింది. తమ మేలు పోయినా సరే, శరణు వచ్చిన వాళ్ళను మంచివాళ్ళు వదలరు.” కారణం ఉదాత్తంగానే వినిపించింది. కానీ అదే ఒక ద్వారం అని, ఆయన వదిలి వచ్చిన లోకమంతా దాని గుండా మళ్ళీ లోపలికి వస్తోందని భాగవతం సున్నితంగా చూపిస్తుంది."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 8: the doe at the river, the lion's roar, the fawn falling into the Gaṇḍakī, the mother's death in a cave; Bharata rescuing and raising the fawn and his daily practices slipping away. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: the same episode, told more briefly.", "భాగవత పురాణం, ఐదవ స్కంధం, 8వ అధ్యాయం: నది దగ్గర లేడి, సింహ గర్జన, గండకీలో పడిన లేడిపిల్ల, గుహలో తల్లి మరణం; భరతుడు పిల్లను కాపాడి పెంచడం, ఆయన నిత్యనియమాలు జారిపోవడం. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: ఇదే ఘట్టం క్లుప్తంగా."]
  ]
 ],
 remember: [
  ["A lion's roar made a pregnant doe leap the river; her fawn fell into the water and she died.", "సింహ గర్జనకు గర్భిణి లేడి నది దాటి దూకింది; పిల్ల నీళ్ళలో పడింది; తల్లి చనిపోయింది."],
  ["{jadabharata|Bharata} saved the {jbfawn|fawn} — an act of pure kindness.", "{jadabharata|భరతుడు} ఆ {jbfawn|లేడిపిల్లను} కాపాడాడు — అది స్వచ్ఛమైన దయ."],
  ["Slowly his love for it pushed out his worship, one practice at a time.", "నెమ్మదిగా దాని మీది ప్రేమ ఒక్కొక్క నియమాన్నీ తోసేసి ఆయన పూజను దూరం చేసింది."]
 ],
 think: ["Saving the fawn was right. Where, do you think, did Bharata's kindness turn into something else?", "లేడిపిల్లను కాపాడటం సరైనదే. భరతుని దయ ఎక్కడ వేరే దానిగా మారిందని మీరు అనుకుంటున్నారు?"]
},
{
 id: "jb-5", sage: "jadabharata", n: 5, order: 5505, date: "2026-11-28",
 title: "The Last Thought", titleTe: "చివరి తలపు",
 src: "Bhāgavata 5.8 · Viṣṇu Purāṇa 2.13 · Bhagavad Gītā 8",
 who: ["jadabharata", "jbfawn", "krishna", "arjuna"],
 pages: [
  [
   ["p", "The {jbfawn|deer} grew. It wandered off into the forest to graze and played with other deer, and sometimes it was late coming back. Then {jadabharata|Bharata} could not sit still. The Bhāgavata gives his anxious thoughts almost word for word, and they sound like any parent waiting at the door:", "{jbfawn|లేడి} పెరిగి పెద్దదైంది. మేత కోసం అడవిలోకి వెళ్ళేది, ఇతర లేళ్ళతో ఆడుకునేది; ఒక్కోసారి తిరిగి రావడం ఆలస్యమయ్యేది. అప్పుడు {jadabharata|భరతుడు} కుదురుగా కూర్చోలేకపోయేవాడు. ఆయన ఆందోళన మాటలను భాగవతం దాదాపు యథాతథంగా ఇస్తుంది — గుమ్మం దగ్గర ఎదురుచూసే ఏ తల్లిదండ్రులవో అనిపిస్తాయి:"],
   ["p", "“Where has the poor little thing gone? Has a wolf caught it, or a tiger? The sun is setting and it isn't home. When will it come back and comfort me? It used to nudge me with its little horns when I sat with my eyes closed in meditation, as if to say, ‘Play with me.’ It used to lick my hands…” He would go and look at its hoof-prints on the ground and sigh. He even looked at the dark mark on the moon and thought, “Is that my deer, taken in by the Moon out of pity?”", "“పాపం ఆ చిన్నది ఎక్కడికి పోయిందో? తోడేలు పట్టుకుందా, పులి పట్టుకుందా? సూర్యుడు అస్తమిస్తున్నాడు, అది ఇంకా ఇంటికి రాలేదు. ఎప్పుడొచ్చి నాకు ఊరట కలిగిస్తుందో? నేను కళ్ళు మూసుకుని ధ్యానంలో ఉంటే చిన్న కొమ్ములతో పొడిచేది — ‘నాతో ఆడుకో’ అన్నట్టు. నా చేతులు నాకేది…” అని నేల మీద దాని గిట్టల గుర్తులు చూసి నిట్టూర్చేవాడు. చంద్రుని మీది నల్లని మచ్చను చూసి కూడా “జాలిపడి చంద్రుడు నా లేడిని తన ఒడిలోకి తీసుకున్నాడా?” అనుకునేవాడు."]
  ],
  [
   ["h", "The great man who forgot", "మరిచిపోయిన మహానుభావుడు"],
   ["p", "Here is the hard part of the story, and the Purāṇas do not soften it. A man who had walked away from an empire, from his wife and his sons, without looking back, now could not bear to be parted from a deer for an afternoon. The Bhāgavata says his heart was so taken up with it that the practice of yoga, the worship of the Lord and the study of the Self all fell away from him. It calls this the ripening of his own past karma, appearing in the shape of a deer.", "ఇది కథలోని కఠినమైన భాగం; పురాణాలు దాన్ని మెత్తగా చేయవు. వెనక్కి తిరిగి చూడకుండా సామ్రాజ్యాన్నీ, భార్యనూ, కొడుకులనూ వదిలి వచ్చిన మనిషి ఇప్పుడు ఒక్క మధ్యాహ్నం లేడికి దూరంగా ఉండలేకపోతున్నాడు. ఆయన మనసంతా దాని మీదే లగ్నమై, యోగాభ్యాసమూ భగవదారాధనా ఆత్మవిచారమూ అన్నీ దూరమయ్యాయని భాగవతం చెబుతుంది. ఆయన పూర్వ కర్మమే లేడి రూపంలో ఫలించిందని అంటుంది."],
   ["p", "Then death came — as it comes to everyone, with no warning about what we will be thinking of. Bharata lay dying in his hermitage, and the deer stood beside him, watching him the way a son watches a dying father, as if grieving. Bharata's eyes were on the deer. His last thought was of the deer. And with that thought in his mind, he left his body.", "అప్పుడు మృత్యువు వచ్చింది — అందరికీ వచ్చినట్టే, ఆ సమయంలో మనం ఏం తలుస్తామో ముందే చెప్పకుండా. భరతుడు ఆశ్రమంలో మరణశయ్య మీద ఉన్నాడు; లేడి పక్కనే నిలబడి, చనిపోతున్న తండ్రిని కొడుకు చూసినట్టు, దుఃఖంతో ఉన్నట్టు, ఆయననే చూస్తోంది. భరతుని కళ్ళు ఆ లేడి మీదే. ఆయన చివరి తలపు ఆ లేడి గురించే. ఆ తలపుతోనే ఆయన దేహం విడిచాడు."]
  ],
  [
   ["h", "What the Gītā says", "గీత ఏమంటుంది"],
   ["p", "The Bhagavad Gītā states the law behind this story. {krishna|Kṛṣṇa} tells {arjuna|Arjuna}:", "ఈ కథ వెనుక ఉన్న నియమాన్ని భగవద్గీత చెబుతుంది. {krishna|కృష్ణుడు} {arjuna|అర్జునునితో} ఇలా అంటాడు:"],
   ["sloka", ["యం యం వాపి స్మరన్ భావం త్యజత్యంతే కలేవరమ్ ।", "తం తమేవైతి కౌంతేయ సదా తద్భావభావితః ॥"], ["yaṃ yaṃ vāpi smaran bhāvaṃ tyajaty ante kalevaram |", "taṃ tam evaiti kaunteya sadā tad-bhāva-bhāvitaḥ ||"], "“Whatever state of being a person remembers when at last he leaves the body, to that very state he goes, O son of Kuntī — for he has always been shaped by it.” (Bhagavad Gītā 8.6)", "“కౌంతేయా! చివరి క్షణంలో దేహం విడిచేటప్పుడు మనిషి ఏ భావాన్ని తలుస్తాడో, ఆ భావాన్నే పొందుతాడు — ఎందుకంటే ఎల్లప్పుడూ ఆ భావంలోనే మునిగి ఉన్నాడు కాబట్టి.” (భగవద్గీత 8.6)"],
   ["p", "The second half of the verse matters most: *sadā tad-bhāva-bhāvitaḥ* — “always steeped in it.” Bharata did not think of the deer at the end by accident. He had thought of it every day, every evening, every hour it was away. The last thought is simply the one we have practised most.", "శ్లోకంలోని రెండవ సగం ముఖ్యం: *సదా తద్భావభావితః* — “ఎల్లప్పుడూ ఆ భావంలోనే మునిగి.” చివర్లో భరతుడు లేడిని తలచుకోవడం యాదృచ్ఛికం కాదు. ప్రతి రోజూ, ప్రతి సాయంత్రం, అది దూరంగా ఉన్న ప్రతి గంటా దాన్నే తలచాడు. చివరి తలపు అంటే మనం ఎక్కువగా అలవాటు చేసుకున్న తలపే."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 8: Bharata's anxious thoughts when the deer is away (the hoof-prints, the mark on the moon); his practices falling away; his death with the deer beside him and his mind on it. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: he died gazing at the deer, his mind fixed on it. Bhagavad Gītā 8.6 (quoted).", "భాగవత పురాణం, ఐదవ స్కంధం, 8వ అధ్యాయం: లేడి దూరంగా ఉన్నప్పుడు భరతుని ఆందోళన (గిట్టల గుర్తులు, చంద్రుని మచ్చ); నియమాలు జారిపోవడం; పక్కన లేడి ఉండగా, మనసు దాని మీదే ఉండగా మరణం. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: లేడిని చూస్తూ, దాని మీదే మనసు నిలిపి కన్నుమూశాడు. భగవద్గీత 8.6 (ఉదహరించాం)."]
  ]
 ],
 remember: [
  ["{jadabharata|Bharata}, who gave up an empire, could not bear to be parted from a deer.", "సామ్రాజ్యాన్ని వదిలిన {jadabharata|భరతుడు} ఒక లేడికి దూరంగా ఉండలేకపోయాడు."],
  ["He died with the {jbfawn|deer} beside him and his mind fixed on it.", "పక్కన {jbfawn|లేడి} ఉండగా, మనసు దాని మీదే నిలిచి ఉండగా కన్నుమూశాడు."],
  ["The Gītā says we go to what we remember at the end — and we remember what we have always dwelt on.", "చివర్లో తలచిన దాన్నే పొందుతామని, ఎప్పుడూ మునిగి ఉన్న దాన్నే చివర్లో తలుస్తామని గీత చెబుతుంది."]
 ],
 think: ["What do you think about most often during an ordinary day? If “the last thought is the one we have practised most,” what would you like to practise?", "ఒక మామూలు రోజులో మీరు ఎక్కువగా దేని గురించి ఆలోచిస్తారు? “చివరి తలపు అంటే ఎక్కువగా అలవాటు చేసుకున్న తలపే” అయితే, మీరు దేన్ని అలవాటు చేసుకోవాలనుకుంటారు?"]
},
{
 id: "jb-6", sage: "jadabharata", n: 6, order: 5506, date: "2026-11-28",
 title: "A Deer Who Remembered", titleTe: "గతం గుర్తున్న లేడి",
 src: "Bhāgavata 5.8 · Viṣṇu Purāṇa 2.13",
 who: ["jadabharata", "pulaha", "pulastya"],
 pages: [
  [
   ["p", "{jadabharata|Bharata} was born again — as a deer, on the mountain the Bhāgavata names Kālañjara. But something unusual happened. Because of the worship and tapas of his past life, he did not forget who he had been. The deer remembered everything: the throne, the hermitage, the river, the fawn, and how his mind had slipped.", "{jadabharata|భరతుడు} మళ్ళీ పుట్టాడు — లేడిగా, భాగవతం కాలంజరం అని పేరు చెప్పే కొండ మీద. కానీ ఒక అసాధారణమైనది జరిగింది. పూర్వ జన్మలో చేసిన పూజ వల్లా తపస్సు వల్లా, తానెవరో ఆయన మరిచిపోలేదు. ఆ లేడికి అన్నీ గుర్తున్నాయి: సింహాసనం, ఆశ్రమం, నది, లేడిపిల్ల, మనసు ఎలా జారిపోయిందో."],
   ["p", "The Bhāgavata gives the deer's sorrow: “Alas, what has happened to me! I left everything for the Lord, I lived alone in a holy forest, I fixed my mind on Him — and then, fool that I am, I let it all go for the sake of a young deer.” There was no anger at the fawn in this, and no self-pity. It was simply seeing clearly where he had gone wrong.", "ఆ లేడి పశ్చాత్తాపాన్ని భాగవతం ఇలా చెబుతుంది: “అయ్యో, నాకేం జరిగింది! స్వామి కోసం అన్నీ వదిలాను, పుణ్యారణ్యంలో ఒంటరిగా ఉన్నాను, మనసును ఆయన మీద నిలిపాను — తీరా మూర్ఖుడినై ఒక లేడిపిల్ల కోసం అదంతా పోగొట్టుకున్నాను.” ఇందులో లేడిపిల్ల మీద కోపం లేదు, తన మీద జాలీ లేదు. ఎక్కడ తప్పాడో స్పష్టంగా చూడటం మాత్రమే."]
  ],
  [
   ["h", "Back to Śālagrāma", "మళ్ళీ సాలగ్రామానికి"],
   ["p", "So the deer did what no ordinary deer would do. It left its mother and its herd, walked all the way from Kālañjara back to Śālagrāma, to the hermitage of {pulastya|Pulastya} and {pulaha|Pulaha} on the Gaṇḍakī — the very place where it had once been a king and a sage — and lived there alone and quiet.", "అందుకే ఆ లేడి ఏ మామూలు లేడీ చేయని పని చేసింది. తల్లినీ మందనూ వదిలి, కాలంజరం నుండి నడుచుకుంటూ మళ్ళీ సాలగ్రామానికి, గండకీ తీరంలోని {pulastya|పులస్త్య}, {pulaha|పులహుల} ఆశ్రమానికి వచ్చింది — ఒకప్పుడు తాను రాజుగా, మునిగా ఉన్న చోటికే — అక్కడ ఒంటరిగా, మౌనంగా ఉంది."],
   ["p", "It made friends with no one, this time. It ate only dry leaves and grass that had already fallen, so as not to harm even a living plant. It stayed near the sages and listened. And it waited, patiently, for this life to end.", "ఈసారి అది ఎవరితోనూ స్నేహం చేయలేదు. బతికి ఉన్న మొక్కకు కూడా హాని చేయకూడదని, అప్పటికే రాలిపడిన ఎండు ఆకులూ గడ్డీ మాత్రమే తింది. మునుల దగ్గరే ఉండి వినేది. ఈ జన్మ ముగిసేవరకూ ఓపికగా ఎదురుచూసింది."]
  ],
  [
   ["p", "When the end came, the deer went down to the holy river and, standing in its water, gave up the deer's body. The Purāṇas say it left that life with its mind steady — the opposite of how it had left the life before.", "అంతం వచ్చినప్పుడు ఆ లేడి పవిత్ర నదిలోకి దిగి, ఆ నీటిలో నిలబడి లేడి దేహాన్ని విడిచింది. ఆ జన్మను నిశ్చలమైన మనసుతో విడిచిందని పురాణాలు చెబుతాయి — అంతకు ముందు జన్మను విడిచిన తీరుకు పూర్తిగా విరుద్ధంగా."],
   ["dyk", "🔁", "Bharata's three lives circle around one river. He came to the Gaṇḍakī as a king, fell there as a sage, and returned there as a deer to set things right.", "భరతుని మూడు జన్మలూ ఒక్క నది చుట్టూ తిరుగుతాయి. రాజుగా గండకీకి వచ్చాడు, మునిగా అక్కడే జారిపడ్డాడు, లేడిగా అక్కడికే తిరిగి వచ్చి సరిదిద్దుకున్నాడు."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 8: born as a deer on Kālañjara with memory of his past life; his repentance; leaving his mother and returning to Pulastya and Pulaha's hermitage at Śālagrāma; living on dry leaves; leaving the body in the river. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: born as a deer remembering his past, he went to Śālagrāma, lived on grass and leaves, and died there.", "భాగవత పురాణం, ఐదవ స్కంధం, 8వ అధ్యాయం: పూర్వజన్మ స్మృతితో కాలంజరంలో లేడిగా జననం; పశ్చాత్తాపం; తల్లిని వదిలి సాలగ్రామంలోని పులస్త్య పులహాశ్రమానికి రావడం; ఎండు ఆకులు తిని బతకడం; నదిలో దేహత్యాగం. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: గతం గుర్తున్న లేడిగా పుట్టి సాలగ్రామానికి వెళ్ళి, గడ్డీ ఆకులూ తిని, అక్కడే కన్నుమూశాడు."]
  ]
 ],
 remember: [
  ["{jadabharata|Bharata} was born a deer at Kālañjara but remembered his past life.", "{jadabharata|భరతుడు} కాలంజరంలో లేడిగా పుట్టినా పూర్వజన్మ గుర్తుంది."],
  ["The deer left its herd, returned to the hermitage on the Gaṇḍakī and lived on fallen leaves.", "ఆ లేడి మందను వదిలి గండకీ తీరపు ఆశ్రమానికి తిరిగి వచ్చి రాలిన ఆకులు తిని బతికింది."],
  ["It left that body in the holy river with a steady mind.", "నిశ్చలమైన మనసుతో పవిత్ర నదిలో ఆ దేహం విడిచింది."]
 ],
 think: ["The deer did not blame the fawn; it saw where its own mind had slipped. Why is it easier to blame something outside us than to see our own part?", "లేడి లేడిపిల్లను నిందించలేదు; తన మనసు ఎక్కడ జారిందో చూసుకుంది. మన పాత్రను చూసుకోవడం కంటే బయటి దాన్ని నిందించడం ఎందుకు సులువుగా ఉంటుంది?"]
},
{
 id: "jb-7", sage: "jadabharata", n: 7, order: 5507, date: "2026-11-28",
 title: "The Brāhmaṇa Who Would Not Speak", titleTe: "మాట్లాడని బ్రాహ్మణుడు",
 src: "Bhāgavata 5.9 · Viṣṇu Purāṇa 2.13",
 who: ["jadabharata", "jbfather", "angiras"],
 pages: [
  [
   ["p", "For his third life {jadabharata|Bharata} was born into a family of brāhmaṇas. The Bhāgavata says his {jbfather|father} was a learned, self-controlled brāhmaṇa of {angiras|Aṅgiras'} line, who had nine sons by his elder wife. By his younger wife he had twins — a boy and a girl — and the boy was Bharata. The Viṣṇu Purāṇa says only that he was born in a pure family of brāhmaṇas devoted to yoga.", "మూడవ జన్మలో {jadabharata|భరతుడు} బ్రాహ్మణ కుటుంబంలో పుట్టాడు. ఆయన {jbfather|తండ్రి} {angiras|అంగిరస} గోత్రపు, విద్వాంసుడైన, జితేంద్రియుడైన బ్రాహ్మణుడని, పెద్ద భార్యకు తొమ్మిది మంది కొడుకులున్నారని భాగవతం చెబుతుంది. చిన్న భార్యకు కవలలు పుట్టారు — ఒక అబ్బాయి, ఒక అమ్మాయి; ఆ అబ్బాయే భరతుడు. యోగనిష్ఠ ఉన్న పవిత్ర బ్రాహ్మణ కుటుంబంలో పుట్టాడని మాత్రమే విష్ణు పురాణం చెబుతుంది."],
   ["p", "Again he remembered everything — now two lives back. And this time he made a decision. “Attachment brought me down once. I will not let anyone tie me again — not a father, not a brother, not a friend.” So he behaved, from childhood, as if he were dull, deaf and simple. He would not show his learning. He would not show his feelings. He would let the world think him a fool, so that the world would leave him alone with the Lord.", "మళ్ళీ ఆయనకు అన్నీ గుర్తున్నాయి — ఈసారి రెండు జన్మల వెనకటిది కూడా. ఈసారి ఒక నిర్ణయం తీసుకున్నాడు: “బంధం నన్ను ఒకసారి కిందకు లాగింది. ఇంకెవరూ నన్ను కట్టిపడేయకుండా చూసుకుంటాను — తండ్రి అయినా, అన్న అయినా, స్నేహితుడైనా.” అందుకే చిన్నప్పటి నుండీ మందుడిలా, చెవిటివాడిలా, అమాయకుడిలా ఉండేవాడు. తన జ్ఞానాన్ని బయటపెట్టలేదు; తన భావాలను చూపించలేదు. లోకం తనను మూర్ఖుడని అనుకుంటే, లోకం తనను భగవంతునితో ఒంటరిగా వదిలేస్తుంది."]
  ],
  [
   ["h", "A father who kept trying", "పట్టు వదలని తండ్రి"],
   ["p", "His father loved him dearly. He performed the boy's upanayana, the sacred-thread ceremony, and set out to teach him — cleanliness, the daily rites, the Gāyatrī. The Bhāgavata says he spent a whole spring and summer trying to teach him the Gāyatrī with its opening syllables, and the boy would not learn it properly. He did things backwards on purpose, or did nothing at all. The father never gave up. He died still hoping his son would one day become a scholar.", "తండ్రికి అతనంటే ప్రాణం. ఉపనయనం చేసి చదువు చెప్పడం మొదలుపెట్టాడు — శౌచం, నిత్యకర్మలు, గాయత్రి. ఒక వసంతమూ ఒక వేసవీ మొత్తం వ్యాహృతులతో గాయత్రిని నేర్పించాలని ప్రయత్నించాడని, అబ్బాయి సరిగ్గా నేర్చుకోలేదని భాగవతం చెబుతుంది. కావాలనే తలకిందులుగా చేసేవాడు, లేదా అసలేమీ చేసేవాడు కాదు. తండ్రి మాత్రం ఆశ వదల్లేదు. కొడుకు ఎప్పటికైనా పండితుడవుతాడనే ఆశతోనే కన్నుమూశాడు."],
   ["p", "When the father died, the Bhāgavata says, Bharata's mother placed the twins in the care of her co-wife and followed her husband in death, as was done in some families of that age. It tells this in a single plain sentence and moves on, and so shall we. The boy now lived in a house with nine half-brothers who had no idea who he was.", "తండ్రి చనిపోయినప్పుడు భరతుని తల్లి కవలలను సవతికి అప్పగించి, ఆ కాలంలో కొన్ని కుటుంబాలలో జరిగినట్టు, భర్తతో పాటే తానూ ప్రాణం విడిచిందని భాగవతం చెబుతుంది. అది ఒక్క వాక్యంలో సూటిగా చెప్పి ముందుకు వెళ్తుంది; మనమూ అలాగే వెళ్దాం. ఇప్పుడా అబ్బాయి తానెవరో ఏమాత్రం తెలియని తొమ్మిది మంది సవతి అన్నల ఇంట్లో ఉన్నాడు."]
  ],
  [
   ["h", "The family's field-hand", "ఇంటి పాలేరు"],
   ["p", "His brothers were learned in the Vedic rites but, says the Bhāgavata, knew nothing of the Self. They decided he was useless, stopped trying to teach him, and put him to work. Anyone who wanted a job done could order him about, and he did it without complaint, for whatever wages or food he was given. People in the village called him mad, dull, deaf. Some mocked him; he did not answer.", "అన్నలు వైదిక కర్మలలో పండితులే గానీ ఆత్మజ్ఞానం గురించి ఏమీ తెలియనివారని భాగవతం చెబుతుంది. వీడు ఎందుకూ పనికిరాడని తేల్చి, చదువు చెప్పడం మానేసి, పనులకు పెట్టారు. ఎవరు పని చెప్పినా, ఏ కూలి ఇచ్చినా, ఏ తిండి పెట్టినా ఫిర్యాదు లేకుండా చేసేవాడు. ఊళ్ళో అందరూ పిచ్చివాడు, మొద్దు, చెవిటివాడు అనేవారు. కొందరు ఎగతాళి చేసేవారు; ఆయన జవాబు చెప్పేవాడు కాదు."],
   ["p", "They fed him broken rice, oil-cake, husks, burnt scrapings from the bottom of the pot — and he ate it as if it were nectar. He wore a dirty cloth and a soiled sacred thread. Yet his body was strong and well-built, like a great bull, and he felt neither heat nor cold. His brothers set him to guard the paddy field at night, and he sat there in the dark, upright and still, in the posture of a yogi — watching over the crop, and watching the Self.", "నూకలు, తెలకపిండి, పొట్టు, కుండ అడుగున మాడిన అడుగుబొడుగు పెట్టేవారు — ఆయన అమృతంలా తినేవాడు. మాసిన గుడ్డ, మురికి జంధ్యం. అయినా ఆయన దేహం పెద్ద ఎద్దులా బలంగా, దృఢంగా ఉండేది; ఎండా చలీ తెలిసేవి కావు. అన్నలు రాత్రిపూట వరిపొలానికి కాపలాగా పెట్టారు; ఆయన చీకట్లో నిటారుగా, నిశ్చలంగా, యోగాసనంలో కూర్చునేవాడు — పంటకు కాపలా కాస్తూ, ఆత్మను గమనిస్తూ."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 9: birth in the family of a brāhmaṇa of Aṅgiras' line, as a twin by the younger wife; remembering his past; acting dull; his father's efforts to teach him the Gāyatrī; the father's death and the mother following him; the brothers putting him to work and feeding him scraps; guarding the field at night. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: born in a family of pure yogins, he acted like a dull man and did menial work.", "భాగవత పురాణం, ఐదవ స్కంధం, 9వ అధ్యాయం: అంగిరస గోత్రపు బ్రాహ్మణుని చిన్న భార్యకు కవలలలో ఒకడిగా జననం; పూర్వజన్మ స్మృతి; మందుడిలా ఉండటం; గాయత్రి నేర్పాలని తండ్రి ప్రయత్నం; తండ్రి మరణం, తల్లి ఆయనను అనుసరించడం; అన్నలు పనులకు పెట్టి మిగిలినది తినిపించడం; రాత్రి పొలానికి కాపలా. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: యోగుల పవిత్ర కుటుంబంలో పుట్టి మందుడిలా ఉండి సేవకుని పనులు చేశాడు."]
  ]
 ],
 remember: [
  ["In his third life {jadabharata|Bharata} was born to a brāhmaṇa of Aṅgiras' line and remembered both past lives.", "మూడవ జన్మలో {jadabharata|భరతుడు} అంగిరస గోత్రపు బ్రాహ్మణునికి పుట్టాడు; రెండు పూర్వజన్మలూ గుర్తున్నాయి."],
  ["To avoid all attachment he acted dull, so people called him Jaḍa.", "ఏ బంధమూ రాకూడదని మందుడిలా ఉన్నాడు; అందుకే జనం జడుడు అన్నారు."],
  ["His brothers made him a field-hand; he ate scraps as nectar and guarded the field at night in meditation.", "అన్నలు పాలేరుగా చేశారు; మిగిలిన తిండిని అమృతంలా తిన్నాడు; రాత్రి ధ్యానంలో పొలానికి కాపలా కాశాడు."]
 ],
 think: ["Bharata let everyone think he was a fool. Is it ever wise to let people misjudge you? When might it be unwise?", "భరతుడు అందరూ తనను మూర్ఖుడనుకునేలా చేశాడు. ఇతరులు మనల్ని తప్పుగా అంచనా వేయనివ్వడం ఎప్పుడైనా తెలివైన పనేనా? ఎప్పుడు కాదు?"]
},
{
 id: "jb-8", sage: "jadabharata", n: 8, order: 5508, date: "2026-11-28",
 title: "Before Bhadrakālī", titleTe: "భద్రకాళి ఎదుట",
 src: "Bhāgavata 5.9",
 who: ["jadabharata", "robberchief", "bhadrakali"],
 pages: [
  [
   ["p", "This episode is told in the Bhāgavata; the Viṣṇu Purāṇa does not have it. It is the darkest night of {jadabharata|Bharata's} third life, and the Purāṇa tells it plainly, so we will too.", "ఈ ఘట్టం భాగవతంలో ఉంది; విష్ణు పురాణంలో లేదు. {jadabharata|భరతుని} మూడవ జన్మలో ఇది అత్యంత చీకటి రాత్రి; పురాణం దీన్ని సూటిగా చెబుతుంది, మనమూ అలాగే చెబుతాం."],
   ["p", "There was a {robberchief|chief of a band of robbers} who longed for a son. He decided to win one from the goddess {bhadrakali|Bhadrakālī} by offering her a human being — a terrible, forbidden thing. His men had caught a man for the purpose, but in the night the victim escaped. The robbers searched in the dark and could not find him.", "కొడుకు కోసం తపించిపోతున్న ఒక {robberchief|దొంగల నాయకుడు} ఉన్నాడు. {bhadrakali|భద్రకాళి} అమ్మవారికి ఒక మనిషిని బలి ఇచ్చి కొడుకును పొందాలనుకున్నాడు — అది ఘోరమైన, నిషిద్ధమైన పని. అందుకోసం అతని మనుషులు ఒక మనిషిని పట్టుకొచ్చారు; కానీ రాత్రి అతను తప్పించుకుపోయాడు. దొంగలు చీకట్లో వెతికారు, దొరకలేదు."]
  ],
  [
   ["h", "The man in the field", "పొలంలో మనిషి"],
   ["p", "Then, by chance, they came upon a strong young man sitting perfectly still in the middle of a paddy field at midnight, guarding the crop. It was Bharata. “Here's one — a fine, strong victim,” they said. They tied him with ropes and led him away, and he went with them without a word. He did not struggle, did not plead, did not even ask where they were taking him.", "అప్పుడు అనుకోకుండా వాళ్ళకు అర్ధరాత్రి వరిపొలం మధ్యలో పంటకు కాపలా కాస్తూ కదలకుండా కూర్చున్న బలమైన యువకుడు కనిపించాడు. అతనే భరతుడు. “ఇదిగో, మంచి బలమైన బలి దొరికింది” అనుకుని తాళ్ళతో కట్టి తీసుకుపోయారు. ఆయన ఒక్క మాట కూడా లేకుండా వెంట వెళ్ళాడు. పెనుగులాడలేదు, బతిమాలలేదు, ఎక్కడికి తీసుకుపోతున్నారని కూడా అడగలేదు."],
   ["p", "At the goddess's shrine they bathed him, dressed him in new clothes, put ornaments, sandal-paste and garlands on him, fed him, and led him before the image with music, drums and lamps, as their dreadful rite required. They made him sit down before the goddess. The chief's priest took up a great sharp sword, consecrated it with mantras, and raised it to strike.", "అమ్మవారి గుడి దగ్గర ఆయనకు స్నానం చేయించి, కొత్త బట్టలు కట్టి, నగలు, గంధం, పూలమాలలు వేసి, భోజనం పెట్టి, వాళ్ళ భయంకర కర్మ ప్రకారం వాద్యాలతో, డప్పులతో, దీపాలతో విగ్రహం ఎదుటకు తెచ్చారు. అమ్మవారి ముందు కూర్చోబెట్టారు. నాయకుని పూజారి పెద్ద పదునైన కత్తి తీసి, మంత్రాలతో అభిమంత్రించి, వేయడానికి పైకెత్తాడు."]
  ],
  [
   ["h", "The goddess will not allow it", "అమ్మవారు ఒప్పుకోలేదు"],
   ["p", "At that moment, says the Bhāgavata, {bhadrakali|Bhadrakālī} herself could not bear it. She felt the blazing holiness of the man they were about to kill — a man who saw no enemy in anyone, a friend of all creatures — and the image itself seemed to burst apart. The goddess came forth in her fearsome form, blazing with anger, snatched the very sword from their hands, and with it struck down the {robberchief|chief} and all his men. Their evil rite ended with them.", "ఆ క్షణంలో {bhadrakali|భద్రకాళి} అమ్మవారే సహించలేకపోయిందని భాగవతం చెబుతుంది. ఎవరిలోనూ శత్రువును చూడని, అన్ని ప్రాణులకూ మిత్రుడైన ఆ మనిషి నుండి వెలువడే దివ్య తేజస్సును ఆమె అనుభవించింది — విగ్రహమే బద్దలైనట్టు, అమ్మవారు ఉగ్రరూపంతో, కోపంతో జ్వలిస్తూ బయటకు వచ్చింది. వాళ్ళ చేతిలోని ఆ కత్తినే లాక్కుని, దానితోనే {robberchief|నాయకుడినీ} అతని మనుషులందరినీ సంహరించింది. వాళ్ళ దుష్ట కర్మ వాళ్ళతోనే ముగిసింది."],
   ["p", "And Bharata? He simply got up and went back to his field. The Bhāgavata draws the lesson: for those who have truly given up the idea that the body is the Self, who bear no hatred to any creature, the Lord himself stands guard — even under the raised sword. It is no surprise, it says, that such a person is protected.", "మరి భరతుడు? లేచి తన పొలానికి తిరిగి వెళ్ళిపోయాడు. భాగవతం చెప్పే పాఠం: దేహమే నేను అనే భావనను నిజంగా వదిలినవాళ్ళను, ఏ ప్రాణి మీదా ద్వేషం లేనివాళ్ళను, ఎత్తిన కత్తి కింద ఉన్నా భగవంతుడే కాపాడతాడు. అలాంటివాళ్ళు రక్షింపబడటంలో ఆశ్చర్యం ఏమీ లేదంటుంది."],
   ["dyk", "⚖️", "The Bhāgavata calls the robbers' rite adharma, against every scripture. The goddess they meant to please was the one who stopped it.", "దొంగల ఆ కర్మ అన్ని శాస్త్రాలకూ విరుద్ధమైన అధర్మమని భాగవతం అంటుంది. వాళ్ళు సంతోషపెట్టాలనుకున్న అమ్మవారే దాన్ని ఆపింది."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 9: the robber chief's wish for a son and his planned human sacrifice to Bhadrakālī; the escaped victim; Jaḍabharata seized from the field at night, adorned and brought before the image; the goddess coming forth and slaying the robbers with their own sword; the Purāṇa's comment on the protection of those who hate no one. This episode is not in the Viṣṇu Purāṇa's telling.", "భాగవత పురాణం, ఐదవ స్కంధం, 9వ అధ్యాయం: కొడుకు కోసం దొంగల నాయకుడు భద్రకాళికి నరబలి తలపెట్టడం; బలి తప్పించుకోవడం; రాత్రి పొలంలో జడభరతుని పట్టుకుని అలంకరించి విగ్రహం ఎదుటకు తేవడం; అమ్మవారు బయటకు వచ్చి వాళ్ళ కత్తితోనే దొంగలను సంహరించడం; ఎవరినీ ద్వేషించనివాళ్ళ రక్షణపై పురాణ వ్యాఖ్య. విష్ణు పురాణ కథనంలో ఈ ఘట్టం లేదు."]
  ]
 ],
 remember: [
  ["Robbers seized {jadabharata|Jaḍabharata} from a field at night to sacrifice him to {bhadrakali|Bhadrakālī}.", "{bhadrakali|భద్రకాళికి} బలి ఇవ్వడానికి దొంగలు రాత్రి పొలంలో {jadabharata|జడభరతుని} పట్టుకుపోయారు."],
  ["He went without fear or a word; the goddess came forth and destroyed the robbers.", "భయమూ మాటా లేకుండా వెళ్ళాడు; అమ్మవారు బయటకు వచ్చి దొంగలను సంహరించింది."],
  ["The Bhāgavata says the Lord guards those who hate no creature.", "ఏ ప్రాణినీ ద్వేషించనివాళ్ళను భగవంతుడే కాపాడతాడని భాగవతం చెబుతుంది."]
 ],
 think: ["Jaḍabharata did not resist or plead. Was that courage, trust, or something else? What would you have felt in his place?", "జడభరతుడు ఎదిరించలేదు, బతిమాలలేదు. అది ధైర్యమా, నమ్మకమా, ఇంకేదైనానా? ఆయన స్థానంలో మీకేం అనిపించేది?"]
},
{
 id: "jb-9", sage: "jadabharata", n: 9, order: 5509, date: "2026-11-28",
 title: "The Palanquin on the Ikṣumatī", titleTe: "ఇక్షుమతీ తీరంలో పల్లకీ",
 src: "Bhāgavata 5.10 · Viṣṇu Purāṇa 2.13",
 who: ["jadabharata", "sauvira", "kapila"],
 pages: [
  [
   ["p", "In those days {sauvira|Rahūgaṇa}, king of Sindhu and Sauvīra, set out to visit the sage {kapila|Kapila} at his hermitage, to ask him about the Self and what is truly worth seeking. The Viṣṇu Purāṇa calls him simply “the king of Sauvīra”; the Bhāgavata gives his name. He travelled in a palanquin carried on the shoulders of bearers, along the bank of the river Ikṣumatī.", "ఆ రోజుల్లో సింధు-సౌవీర దేశాల రాజు {sauvira|రహూగణుడు} ఆత్మ గురించీ, నిజంగా ఏది కోరదగినదో దాని గురించీ అడగడానికి {kapila|కపిల} మహర్షి ఆశ్రమానికి బయలుదేరాడు. విష్ణు పురాణం అతన్ని “సౌవీర రాజు” అని మాత్రమే అంటుంది; భాగవతం పేరు చెబుతుంది. బోయీలు భుజాల మీద మోసే పల్లకీలో ఇక్షుమతీ నది ఒడ్డు వెంబడి ప్రయాణిస్తున్నాడు."],
   ["p", "One bearer was missing. The king's men looked around for someone to fill the place, and there on the riverbank sat a strong, sturdy young brāhmaṇa doing nothing in particular. “He'll do — he's built like an ox,” they said, and put the pole on his shoulder. {jadabharata|Jaḍabharata} took it without a word.", "బోయీలలో ఒకడు తక్కువయ్యాడు. రాజభటులు ఆ స్థానంలో ఎవరినైనా పెట్టాలని చుట్టూ చూశారు; నది ఒడ్డున ఏ పనీ లేకుండా కూర్చున్న బలమైన, దిట్టమైన బ్రాహ్మణ యువకుడు కనిపించాడు. “ఇతను సరిపోతాడు — ఎద్దులా ఉన్నాడు” అని పల్లకీ కర్ర అతని భుజాన పెట్టారు. {jadabharata|జడభరతుడు} ఒక్క మాట లేకుండా మోశాడు."]
  ],
  [
   ["h", "An arrow's length ahead", "బాణం దూరం ముందుకు చూపు"],
   ["p", "But he walked differently from the others. He kept his eyes on the ground an arrow's length ahead, and whenever he saw an ant or a small creature on the path he stepped around it or over it, so as not to crush it. So his steps were uneven, and the palanquin lurched and jolted.", "కానీ ఆయన మిగిలినవాళ్ళలా నడవలేదు. బాణం దూరం ముందు నేల మీదే చూపు నిలిపి, దారిలో చీమో చిన్న ప్రాణో కనిపిస్తే తొక్కకుండా పక్కకో పైకో అడుగు వేసేవాడు. దాంతో అడుగులు సమంగా పడలేదు; పల్లకీ ఊగుతూ కుదుపులకు లోనైంది."],
   ["p", "The king called out. “What's this? Why are you walking so badly?” The bearers said, “It's not us, lord — it's the new man.” The king, a little amused and a little irritated, spoke to Jaḍabharata with heavy sarcasm: “Oh, my poor brother, you must be so tired! You've carried this all alone for such a long way. And you are not stout or strong at all — and old age has caught you too, I see.” Jaḍabharata was young and very strong. He said nothing, and went on walking just as before.", "రాజు అరిచాడు: “ఏమిటిది? ఇంత అడ్డదిడ్డంగా ఎందుకు నడుస్తున్నారు?” బోయీలు “మేము కాదు ప్రభూ — కొత్తవాడు” అన్నారు. రాజు కాస్త సరదాగా, కాస్త చిరాగ్గా జడభరతునితో ఎత్తిపొడుపుగా అన్నాడు: “అయ్యో పాపం సోదరా, ఎంత అలసిపోయావో! ఇంత దూరం ఒక్కడివే మోశావు. పైగా నువ్వు బలిష్ఠుడివీ కావు, దిట్టమైనవాడివీ కావు — ముసలితనం కూడా వచ్చేసినట్టుంది.” జడభరతుడు యువకుడు, మహాబలుడు. ఏమీ అనలేదు; ఇంతకు ముందులాగే నడుస్తూ ఉన్నాడు."]
  ],
  [
   ["h", "The king loses his temper", "రాజుకు కోపం వచ్చింది"],
   ["p", "The palanquin jolted again. Now the king was really angry. “What! Are you a corpse that walks? You ignore your master's order! I'll punish you the way Yama punishes sinners — then you'll come to your senses.” The man of the people, the man nobody listened to, the “dull” one, now spoke for the first time — and smiled as he did.", "పల్లకీ మళ్ళీ కుదిపింది. ఇప్పుడు రాజుకు నిజంగా కోపం వచ్చింది. “ఏమిటీ! నువ్వు నడిచే శవానివా? యజమాని ఆజ్ఞను లెక్కచేయవా! యముడు పాపులను దండించినట్టు నిన్ను దండిస్తాను — అప్పుడు బుద్ధి వస్తుంది.” అప్పుడు ఎవరూ లెక్కచేయని ఆ “మొద్దు” మొదటిసారి నోరు విప్పాడు — చిరునవ్వుతో."],
   ["p", "“What you said, hero, was meant as mockery — but it is simply true. Weight belongs to the one who carries it; I am not this body. Fat or thin, tired or strong, young or old — these belong to the body, not to the Self. ‘Master’ and ‘servant’ last only a little while; they change places. If you really think you are my master, tell me what I should do. But to punish a man who is already ‘dull and mad’ is like grinding flour that is already ground.” Then he went on carrying the palanquin, just as before.", "“వీరుడా, మీరు ఎగతాళిగా అన్నారు — కానీ అది నిజమే. బరువు మోసేవాడిది; నేను ఈ దేహం కాదు. లావూ సన్నమూ, అలసటా బలమూ, యవ్వనమూ ముసలితనమూ — ఇవి దేహానివి, ఆత్మవి కావు. ‘యజమాని’, ‘సేవకుడు’ అనేవి కొంతకాలమే; తారుమారవుతుంటాయి. నేను మీకు సేవకుడినని మీరు నిజంగా అనుకుంటే నేనేం చేయాలో చెప్పండి. కానీ అప్పటికే ‘మొద్దూ పిచ్చివాడూ’ అయిన వాడిని దండించడం, పిండిని మళ్ళీ విసిరినట్టే.” ఇలా అని ఇంతకు ముందులాగే పల్లకీ మోస్తూ నడిచాడు."]
  ],
  [
   ["h", "The king at his feet", "ఆయన పాదాల దగ్గర రాజు"],
   ["p", "Rahūgaṇa was no fool; he was, after all, on his way to Kapila to learn about the Self. These few words struck him like lightning. He jumped down from the palanquin, threw himself at the bearer's feet and begged: “Who are you, wandering in disguise with your sacred thread hidden? Are you an avadhūta? Whose son are you? Are you {kapila|Kapila} himself, come to test me? I do not fear Indra's thunderbolt or Śiva's trident or Yama's staff as much as I fear insulting a man like you. Forgive me.”", "రహూగణుడు మూర్ఖుడు కాడు; అసలు ఆత్మ గురించి తెలుసుకోవడానికే కపిలుని దగ్గరకు వెళ్తున్నాడు. ఈ కొన్ని మాటలు అతన్ని పిడుగులా తాకాయి. పల్లకీ నుండి దూకి, ఆ బోయీ పాదాల మీద పడి వేడుకున్నాడు: “జంధ్యం దాచుకుని మారువేషంలో తిరిగే మీరెవరు? అవధూతలా? ఎవరి కొడుకు? నన్ను పరీక్షించడానికి వచ్చిన {kapila|కపిల} మహర్షియే మీరా? ఇంద్రుని వజ్రాయుధానికీ, శివుని త్రిశూలానికీ, యముని దండానికీ భయపడనంతగా మీ లాంటి వాళ్ళను అవమానించడానికి భయపడతాను. నన్ను క్షమించండి.”"],
   ["p", "The Viṣṇu Purāṇa tells the same meeting in its own words. There the king's servant seizes the brāhmaṇa for forced labour; the king asks if he is tired; and the bearer answers that he is not fat, that he did not carry the palanquin, that he is not tired — for the one who carries is the body, set on the earth, and the palanquin rests on the body, not on him. The king, astonished, gets down and asks who he is.", "విష్ణు పురాణం ఇదే కలయికను తనదైన మాటల్లో చెబుతుంది. అక్కడ రాజసేవకుడు ఆ బ్రాహ్మణుని వెట్టిచాకిరీకి పట్టుకుంటాడు; అలసిపోయావా అని రాజు అడుగుతాడు; తాను లావు కాదనీ, పల్లకీ మోయలేదనీ, అలసిపోలేదనీ ఆ బోయీ జవాబిస్తాడు — మోసేది భూమి మీద నిలిచిన దేహం, పల్లకీ ఉన్నది దేహం మీద, తన మీద కాదు. ఆశ్చర్యపోయిన రాజు కిందకు దిగి ఆయనెవరని అడుగుతాడు."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 10: Rahūgaṇa, king of Sindhu and Sauvīra, going to Kapila's hermitage; Jaḍabharata pressed into carrying the palanquin on the Ikṣumatī; walking with eyes an arrow's length ahead to spare small creatures; the king's sarcasm and threat; Jaḍabharata's reply; the king falling at his feet. Viṣṇu Purāṇa, Aṃśa 2, adhyāya 13: the king of Sauvīra, the forced labour, the question “are you tired?” and the answer.", "భాగవత పురాణం, ఐదవ స్కంధం, 10వ అధ్యాయం: సింధు-సౌవీర రాజు రహూగణుడు కపిలాశ్రమానికి వెళ్ళడం; ఇక్షుమతీ తీరంలో జడభరతుని పల్లకీ మోయడానికి పెట్టడం; చిన్న ప్రాణులను తొక్కకుండా బాణం దూరం ముందుకు చూస్తూ నడవడం; రాజు ఎత్తిపొడుపు, బెదిరింపు; జడభరతుని జవాబు; రాజు ఆయన పాదాల మీద పడటం. విష్ణు పురాణం, రెండవ అంశం, 13వ అధ్యాయం: సౌవీర రాజు, వెట్టిచాకిరీ, “అలసిపోయావా?” అన్న ప్రశ్న, దానికి జవాబు."]
  ]
 ],
 remember: [
  ["{sauvira|King Rahūgaṇa} made {jadabharata|Jaḍabharata} carry his palanquin on the way to Kapila.", "కపిలుని దగ్గరకు వెళ్తూ {sauvira|రహూగణ మహారాజు} {jadabharata|జడభరతుని} పల్లకీ మోయించాడు."],
  ["He walked carefully to avoid crushing small creatures, so the palanquin jolted and the king mocked and threatened him.", "చిన్న ప్రాణులను తొక్కకుండా జాగ్రత్తగా నడవడంతో పల్లకీ కుదిపింది; రాజు ఎత్తిపొడిచి బెదిరించాడు."],
  ["His calm answer — “I am not this body” — brought the king down at his feet.", "“నేను ఈ దేహం కాదు” అన్న ఆయన ప్రశాంత జవాబు రాజును ఆయన పాదాల దగ్గరకు తెచ్చింది."]
 ],
 think: ["Jaḍabharata kept silent at the first insult and spoke only at the second. Why might he have chosen that moment to speak?", "మొదటి ఎత్తిపొడుపుకు జడభరతుడు మౌనంగా ఉన్నాడు, రెండవసారి మాత్రమే మాట్లాడాడు. ఆ సమయాన్నే ఆయన ఎందుకు ఎంచుకుని ఉంటాడు?"]
},
{
 id: "jb-10", sage: "jadabharata", n: 10, order: 5510, date: "2026-11-28",
 title: "“Not by Tapas, Not by Sacrifice”", titleTe: "“తపస్సుతో కాదు, యజ్ఞంతో కాదు”",
 src: "Bhāgavata 5.11–5.12 · Viṣṇu Purāṇa 2.13–16",
 who: ["jadabharata", "sauvira", "ribhu", "nidagha", "parashara"],
 pages: [
  [
   ["p", "Now {jadabharata|Jaḍabharata}, the bearer who would not speak, sat down by the river with the king and taught him. The Bhāgavata gives his teaching over two chapters. It begins with the mind.", "ఇప్పుడు మాట్లాడని ఆ బోయీ — {jadabharata|జడభరతుడు} — నది ఒడ్డున రాజుతో కూర్చుని బోధించాడు. భాగవతం ఆ బోధను రెండు అధ్యాయాలలో ఇస్తుంది. అది మనసుతో మొదలవుతుంది."],
   ["p", "“The mind is what binds us and the mind is what frees us,” he said, in substance. “Coloured by its moods and desires, the mind drives a person from body to body, through pleasure and pain, good and bad. Behind it stands the Self, the silent witness, untouched; and the Lord dwells within as the inner guide. As long as the mind is not mastered, a person keeps wandering. So conquer the mind — with the weapon of devotion to the Lord and the guru's feet.”", "ఆయన మాటల సారాంశం ఇది: “బంధించేదీ మనసే, విడిపించేదీ మనసే. తన భావాలతో, కోరికలతో రంగు పులుముకున్న మనసు మనిషిని దేహం నుండి దేహానికి, సుఖదుఃఖాల గుండా, మంచిచెడుల గుండా తిప్పుతుంది. దాని వెనుక ఆత్మ ఉంది — మౌన సాక్షి, దేనికీ అంటనిది; లోపల అంతర్యామిగా భగవంతుడున్నాడు. మనసు వశం కానంతవరకూ మనిషి తిరుగుతూనే ఉంటాడు. కాబట్టి భగవద్భక్తి, గురుపాదాలు అనే ఆయుధంతో మనసును జయించు.”"]
  ],
  [
   ["h", "“Who is the king of Sauvīra?”", "“సౌవీర రాజు ఎవరు?”"],
   ["p", "Then he showed the king how little “king” and “bearer” really mean. “This earth,” he said, “takes many shapes. Out of it come feet, and on the feet ankles, shins, knees, thighs, a waist, a chest, a neck and shoulders. On the shoulders rests a wooden palanquin, and in the palanquin sits something also made of earth, which is called ‘the king of Sauvīra.’ Where among all this earth is the king, and where the bearer? Your pride in being king has no ground under it — it rests on earth carrying earth.”", "తరువాత “రాజు”, “బోయీ” అనే మాటలకు ఎంత తక్కువ అర్థం ఉందో చూపించాడు. “ఈ భూమి ఎన్నో రూపాలు దాలుస్తుంది. దాని నుండి పాదాలు, పాదాల మీద చీలమండలు, పిక్కలు, మోకాళ్ళు, తొడలు, నడుము, ఛాతీ, మెడ, భుజాలు. భుజాల మీద చెక్క పల్లకీ; పల్లకీలో కూర్చున్నది కూడా మట్టితో చేసినదే — దాన్ని ‘సౌవీర రాజు’ అంటారు. ఈ మట్టంతటిలో రాజెక్కడ, బోయీ ఎక్కడ? రాజునన్న మీ గర్వానికి కింద నేలే లేదు — మట్టిని మోసే మట్టి మీద కూర్చుంది” అన్నాడు."],
   ["p", "And then the line that the Bhāgavata is most remembered for in this story — that this knowledge does not come by any of the usual religious means:", "తరువాత ఈ కథలో భాగవతం నుండి ఎక్కువగా గుర్తుంచుకునే మాట — ఈ జ్ఞానం మామూలు ధార్మిక సాధనాలు ఏవీ ఇవ్వలేవని:"],
   ["sloka", ["రహూగణైతత్తపసా న యాతి న చేజ్యయా నిర్వపణాద్గృహాద్వా ।", "న చ్ఛందసా నైవ జలాగ్నిసూర్యైర్వినా మహత్పాదరజోఽభిషేకమ్ ॥"], ["rahūgaṇaitat tapasā na yāti na cejyayā nirvapaṇād gṛhād vā |", "na cchandasā naiva jalāgni-sūryair vinā mahat-pāda-rajo-'bhiṣekam ||"], "“Rahūgaṇa, this knowledge is not reached by tapas, nor by sacrifice, nor by giving, nor by the duties of the householder, nor by Vedic study, nor by worship of water, fire or sun — not without being bathed in the dust of the feet of great souls.” (Bhāgavata 5.12.12)", "“రహూగణా! ఈ జ్ఞానం తపస్సుతో రాదు, యజ్ఞంతో రాదు, దానంతో రాదు, గృహస్థ ధర్మంతో రాదు, వేదాధ్యయనంతో రాదు, జలాగ్ని సూర్యుల ఉపాసనతో కూడా రాదు — మహాత్ముల పాదధూళితో అభిషేకం జరగనిదే.” (భాగవతం 5.12.12)"]
  ],
  [
   ["h", "“I was King Bharata”", "“నేనే భరత మహారాజును”"],
   ["p", "Only now did Jaḍabharata tell the king who he was. “I was once King Bharata. I gave up everything, but I fell for love of a deer, and was born a deer. Because I worshipped the Lord, I did not forget. That is why I now walk among people without letting anyone hold me.” The king, who had shouted at him an hour before, listened with folded hands.", "అప్పుడే జడభరతుడు తానెవరో రాజుకు చెప్పాడు. “ఒకప్పుడు నేను భరత మహారాజును. అన్నీ వదిలాను, కానీ ఒక లేడి మీది ప్రేమతో జారిపడి, లేడిగా పుట్టాను. భగవంతుని ఆరాధించాను కాబట్టి మరిచిపోలేదు. అందుకే ఇప్పుడు ఎవరి పట్టుకూ చిక్కకుండా మనుషుల మధ్య తిరుగుతున్నాను.” గంట ముందు ఆయన మీద అరిచిన రాజు చేతులు జోడించి విన్నాడు."],
   ["p", "In the Viṣṇu Purāṇa the teaching goes another way. The king asks what is the highest good, and Bharata shows that wealth, sons, sacrifice and even heaven are not it — the highest is the one Self in all. Air blowing through the holes of a flute makes many notes, yet the air is one; so the Self is one in all bodies. To make this clear, he tells the king the story of {ribhu|Ṛbhu} and his pupil {nidagha|Nidāgha}, which you can read in full:", "విష్ణు పురాణంలో బోధ వేరే దారిలో వెళ్తుంది. అత్యున్నత శ్రేయస్సు ఏదని రాజు అడుగుతాడు; సంపద, కొడుకులు, యజ్ఞాలు, స్వర్గం కూడా అది కాదని, అన్నిటిలో ఉన్న ఒక్క ఆత్మే అత్యున్నతమని భరతుడు చూపిస్తాడు. వేణువు రంధ్రాల గుండా వీచే గాలి ఎన్నో స్వరాలు పలికిస్తుంది, అయినా గాలి ఒక్కటే; అలాగే అన్ని దేహాలలో ఆత్మ ఒక్కటే. ఇది స్పష్టం చేయడానికి {ribhu|ఋభువు}, ఆయన శిష్యుడు {nidagha|నిదాఘుని} కథ రాజుకు చెబుతాడు — అది పూర్తిగా ఇక్కడ చదవవచ్చు:"],
   ["sglink", "Ṛbhu and Nidāgha: The Guest at the Door", "ఋభువు, నిదాఘుడు: గుమ్మం దగ్గర అతిథి", "rbh-2"],
   ["sglink", "Which Is the King, and Which the Elephant?", "ఏది రాజు, ఏది ఏనుగు?", "rbh-4"],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 11 (the mind as the cause of bondage and freedom; the Self as witness; conquering the mind) and chapter 12 (the earth that carries earth — ‘the king of Sauvīra’; verse 5.12.12 quoted; Jaḍabharata tells his past lives). Viṣṇu Purāṇa, Aṃśa 2, adhyāyas 13–16 (the king's questions; the highest good; the flute; the story of Ṛbhu and Nidāgha told to the king).", "భాగవత పురాణం, ఐదవ స్కంధం, 11వ అధ్యాయం (బంధమోక్షాలకు మనసే కారణం; సాక్షి అయిన ఆత్మ; మనోజయం), 12వ అధ్యాయం (మట్టిని మోసే మట్టి — ‘సౌవీర రాజు’; 5.12.12 శ్లోకం ఉదహరించాం; జడభరతుడు తన పూర్వజన్మలు చెప్పడం). విష్ణు పురాణం, రెండవ అంశం, 13–16 అధ్యాయాలు (రాజు ప్రశ్నలు; పరమార్థం; వేణువు ఉపమానం; రాజుకు చెప్పిన ఋభు-నిదాఘుల కథ)."]
  ]
 ],
 remember: [
  ["{jadabharata|Jaḍabharata} taught that the mind binds and the mind frees, and must be mastered.", "బంధించేదీ విడిపించేదీ మనసేనని, దాన్ని జయించాలని {jadabharata|జడభరతుడు} బోధించాడు."],
  ["King and bearer are both earth carrying earth; the Self is neither.", "రాజూ బోయీ ఇద్దరూ మట్టిని మోసే మట్టే; ఆత్మ ఆ రెండూ కాదు."],
  ["This knowledge comes not by tapas or sacrifice alone but through the grace of great souls.", "ఈ జ్ఞానం తపస్సుతోనో యజ్ఞంతోనో మాత్రమే కాదు, మహాత్ముల అనుగ్రహంతో వస్తుంది."]
 ],
 think: ["Jaḍabharata says “king” and “bearer” are only roles that change places. Which roles in your own life do you sometimes mistake for who you are?", "“రాజు”, “బోయీ” తారుమారయ్యే పాత్రలు మాత్రమే అని జడభరతుడు అంటాడు. మీ జీవితంలో ఏ పాత్రలను ఒక్కోసారి మీరే అనుకుని పొరబడతారు?"]
},
{
 id: "jb-11", sage: "jadabharata", n: 11, order: 5511, date: "2026-11-28",
 title: "The Forest of the World", titleTe: "సంసారమనే అడవి",
 src: "Bhāgavata 5.13–5.14",
 who: ["jadabharata", "sauvira", "shuka", "parikshit"],
 pages: [
  [
   ["p", "Last of all, {jadabharata|Jaḍabharata} gave the king a picture to carry home — a parable that the Bhāgavata tells in one chapter and then, through {shuka|Śuka}, explains in the next. It is the parable of the great forest.", "చివరగా {jadabharata|జడభరతుడు} రాజుకు ఇంటికి తీసుకెళ్ళడానికి ఒక చిత్రం ఇచ్చాడు — భాగవతం ఒక అధ్యాయంలో చెప్పి, తరువాతి అధ్యాయంలో {shuka|శుకుని} ద్వారా వివరించే ఒక ఉపమాన కథ. అదే మహారణ్యం కథ."],
   ["p", "“A band of merchants,” he said, “set out to make money and wandered into a vast forest. Six robbers fell on them and stole their goods. Wolves and jackals dragged off what was left. They pushed through thorny thickets and were stung by gnats and flies. Sometimes they saw a city of gandharvas shimmering in the air and ran towards it — and it vanished. Sometimes they chased a glowing light, thinking it was gold, and it was only a marsh-fire.", "“ఒక వర్తకుల గుంపు,” అన్నాడు, “ధనం సంపాదించాలని బయలుదేరి ఒక పెద్ద అడవిలో దారి తప్పింది. ఆరుగురు దొంగలు మీద పడి సరుకంతా దోచుకున్నారు. మిగిలినది తోడేళ్ళూ నక్కలూ లాక్కుపోయాయి. ముళ్ళ పొదల గుండా తోసుకుని వెళ్ళారు; దోమలూ ఈగలూ కుట్టాయి. ఒక్కోసారి ఆకాశంలో మెరిసే గంధర్వనగరం కనిపించి దాని వైపు పరిగెత్తారు — అది మాయమైంది. ఒక్కోసారి మెరిసే వెలుగును బంగారమనుకుని వెంటపడ్డారు — అది కొరివిదెయ్యం వెలుగు మాత్రమే."]
  ],
  [
   ["p", "“Whirlwinds blew dust into their eyes until they could not see. Crickets shrilled in their ears; owls hooted. They drank from dry riverbeds and found nothing. They begged from each other. A forest fire scorched them. Some sank into the mud; some were bitten by snakes; some climbed creepers hoping to be lifted up and fell. And still they did not leave the forest, but kept walking on, deeper into it, looking for the wealth they had come for.”", "“సుడిగాలులు కళ్ళలో దుమ్ము కొట్టి ఏమీ కనబడకుండా చేశాయి. చెవుల్లో కీచురాళ్ళు అరిచాయి; గుడ్లగూబలు కూశాయి. ఎండిపోయిన నదుల్లో నీళ్ళు తాగబోయి ఏమీ దొరకలేదు. ఒకరినొకరు యాచించారు. కార్చిచ్చు కాల్చింది. కొందరు బురదలో కూరుకుపోయారు; కొందరిని పాములు కాటేశాయి; కొందరు పైకి వెళ్ళొచ్చని తీగలు పట్టుకుని ఎక్కి కింద పడ్డారు. అయినా ఆ అడవిని వదల్లేదు; తాము వెతుక్కుంటూ వచ్చిన సంపద కోసం ఇంకా లోపలికి నడుస్తూనే ఉన్నారు.”"],
   ["h", "What it means", "దాని అర్థం"],
   ["p", "In the next chapter Śuka explains to {parikshit|Parīkṣit}: the forest is worldly life; the merchants are souls seeking happiness; the six robbers are the five senses and the mind, which steal our strength; the wolves and jackals are those who live off us; the city in the air is the dream of lasting comfort; the false gold is wealth that brings no peace; the dust is desire that blinds; the forest fire is grief. The only way out, he says, is the path that Bharata walked — devotion to the Lord and the company of the wise.", "తరువాతి అధ్యాయంలో శుకుడు {parikshit|పరీక్షిత్తుకు} వివరిస్తాడు: అడవి అంటే సంసారం; వర్తకులు సుఖం వెతుక్కునే జీవులు; ఆరుగురు దొంగలు పంచేంద్రియాలూ మనసూ — మన బలాన్ని దోచుకుంటాయి; తోడేళ్ళూ నక్కలూ మన మీద బతికేవాళ్ళు; గాలిలో నగరం శాశ్వత సుఖమనే కల; నకిలీ బంగారం శాంతినివ్వని ధనం; దుమ్ము కళ్ళు కప్పే కోరిక; కార్చిచ్చు శోకం. బయటపడే ఏకైక దారి భరతుడు నడిచిన దారే — భగవద్భక్తి, జ్ఞానుల సాంగత్యం — అని చెబుతాడు."]
  ],
  [
   ["h", "The king set free", "విముక్తుడైన రాజు"],
   ["p", "{sauvira|Rahūgaṇa} bowed again and again. “Today I have been washed by the dust of your feet,” he said. “The idea that I am this body, which I took from ignorance, is gone.” Jaḍabharata, whose heart was as full and calm as the ocean, forgave him completely — he had never been offended in the first place — and walked away along the river, as unattached as before. The king, the Bhāgavata says, gave up his false idea of the self from that day.", "{sauvira|రహూగణుడు} మళ్ళీ మళ్ళీ నమస్కరించాడు. “ఈ రోజు మీ పాదధూళితో నేను శుద్ధి అయ్యాను. అజ్ఞానం వల్ల పట్టుకున్న ‘నేను ఈ దేహం’ అనే భావం పోయింది” అన్నాడు. సముద్రంలా నిండుగా, ప్రశాంతంగా ఉన్న జడభరతుడు అతన్ని పూర్తిగా క్షమించాడు — అసలు ఆయనకు కోపమే రాలేదు — మళ్ళీ ఏ బంధమూ లేకుండా నది వెంట వెళ్ళిపోయాడు. ఆ రోజు నుండి రాజు దేహమే నేను అనే తప్పుడు భావనను వదిలేశాడని భాగవతం చెబుతుంది."],
   ["dyk", "🧭", "Bharata did not lecture the king about his harsh words. He answered with knowledge, and left the king to see the rest himself.", "రాజు కఠినంగా మాట్లాడినందుకు భరతుడు ఉపన్యాసం ఇవ్వలేదు. జ్ఞానంతో జవాబిచ్చాడు; మిగిలినది రాజే తెలుసుకునేలా వదిలేశాడు."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 13 (the parable of the merchants in the great forest: the six robbers, wolves and jackals, thorns and gnats, the gandharva city, the false gold, the whirlwind, the dry river, the forest fire; Rahūgaṇa's gratitude and Jaḍabharata's departure) and chapter 14 (Śuka's explanation of the parable to Parīkṣit).", "భాగవత పురాణం, ఐదవ స్కంధం, 13వ అధ్యాయం (మహారణ్యంలో వర్తకుల ఉపమానం: ఆరుగురు దొంగలు, తోడేళ్ళు నక్కలు, ముళ్ళు దోమలు, గంధర్వనగరం, నకిలీ బంగారం, సుడిగాలి, ఎండిన నది, కార్చిచ్చు; రహూగణుని కృతజ్ఞత, జడభరతుని నిష్క్రమణ), 14వ అధ్యాయం (శుకుడు పరీక్షిత్తుకు ఉపమానాన్ని వివరించడం)."]
  ]
 ],
 remember: [
  ["{jadabharata|Jaḍabharata} compared worldly life to a forest where merchants are robbed, misled and burned, yet keep going deeper.", "దోచుకోబడి, మోసపోయి, కాలిపోయినా వర్తకులు ఇంకా లోపలికి వెళ్ళే అడవితో సంసారాన్ని {jadabharata|జడభరతుడు} పోల్చాడు."],
  ["The six robbers are the five senses and the mind.", "ఆరుగురు దొంగలు అంటే పంచేంద్రియాలూ మనసూ."],
  ["{sauvira|Rahūgaṇa} was freed from thinking he was the body; Bharata walked on, unattached.", "{sauvira|రహూగణుడు} దేహాత్మభావం నుండి విముక్తుడయ్యాడు; భరతుడు ఏ బంధమూ లేకుండా ముందుకు సాగాడు."]
 ],
 think: ["In the parable, the merchants keep chasing a city in the air and gold that is only a marsh-light. What “cities in the air” do people chase today?", "ఉపమానంలో వర్తకులు గాలిలో నగరం వెంటా, కొరివి వెలుగు లాంటి బంగారం వెంటా పరిగెత్తుతారు. ఈ రోజు మనుషులు ఏ “గాలిమేడల” వెంట పరిగెత్తుతున్నారు?"]
},
{
 id: "jb-12", sage: "jadabharata", n: 12, order: 5512, date: "2026-11-28",
 title: "What Jaḍabharata Leaves Us", titleTe: "జడభరతుడు మనకు ఇచ్చేది",
 src: "Bhāgavata 5.14–5.15 · Viṣṇu Purāṇa 2.16 · Mārkaṇḍeya Purāṇa",
 who: ["jadabharata", "sumati_b", "sumati_jada", "jaimini", "parashara", "shuka", "rishabha"],
 pages: [
  [
   ["p", "At the end of {jadabharata|Bharata's} story the Bhāgavata steps back and praises him. No king, it says, can follow the path of this royal sage, the son of Ṛṣabha, even in his mind — any more than a fly can follow Garuḍa through the sky. He gave up, while still young, a wife, children, friends and a kingdom that others long for, as if they were dirt; and he served the Lord. The Purāṇa adds that whoever hears or tells his story with faith is blessed.", "{jadabharata|భరతుని} కథ ముగిశాక భాగవతం వెనక్కి నిలబడి ఆయనను కీర్తిస్తుంది. ఋషభుని కొడుకైన ఈ రాజర్షి దారిని ఏ రాజూ మనసులో కూడా అనుసరించలేడు — ఆకాశంలో గరుడుని ఈగ అనుసరించలేనట్టే అంటుంది. ఇతరులు తపించిపోయే భార్యనూ, పిల్లలనూ, మిత్రులనూ, రాజ్యాన్నీ యవ్వనంలోనే మట్టిలా వదిలి భగవంతుని సేవించాడు. శ్రద్ధతో ఆయన కథ విన్నవాళ్ళూ చెప్పినవాళ్ళూ ధన్యులవుతారని పురాణం చెబుతుంది."],
   ["p", "His line went on without him. His son {sumati_b|Sumati} ruled after him, and the Bhāgavata traces the kings descended from Sumati through many generations. The Viṣṇu Purāṇa, for its part, ends Bharata's teaching with the king of Sauvīra set free — and remember that this whole story is being told by {parashara|Parāśara} to Maitreya, just as the Bhāgavata's is told by {shuka|Śuka} to Parīkṣit.", "ఆయన లేకపోయినా ఆయన వంశం కొనసాగింది. కొడుకు {sumati_b|సుమతి} ఆయన తరువాత ఏలాడు; సుమతి నుండి వచ్చిన రాజులను ఎన్నో తరాల వరకు భాగవతం చెబుతుంది. విష్ణు పురాణం సౌవీర రాజు విముక్తితో భరతుని బోధను ముగిస్తుంది — ఈ కథంతా భాగవతంలో {shuka|శుకుడు} పరీక్షిత్తుకు చెప్పినట్టే, విష్ణు పురాణంలో {parashara|పరాశరుడు} మైత్రేయునికి చెబుతున్నాడని గుర్తుంచుకోండి."]
  ],
  [
   ["h", "Another “dull” boy", "ఇంకో “మొద్దు” అబ్బాయి"],
   ["p", "Jaḍabharata is not the only one of his kind. The Mārkaṇḍeya Purāṇa tells of a brāhmaṇa boy named {sumati_jada|Sumati}, also called Jaḍa, who also remembered his past lives and so behaved like a dullard — until his father questioned him, and the “dull” boy answered with a whole teaching on birth, death and freedom. That story is told to {jaimini|Jaimini} by wise birds:", "జడభరతుడు ఒక్కడే కాదు. మార్కండేయ పురాణంలో {sumati_jada|సుమతి} అనే బ్రాహ్మణ బాలుడు ఉన్నాడు; అతన్నీ జడుడనే అనేవారు; అతనికీ పూర్వజన్మలు గుర్తుండి మొద్దులా ఉండేవాడు — తండ్రి ప్రశ్నించేవరకూ. అప్పుడు ఆ “మొద్దు” జననం, మరణం, మోక్షం గురించి ఒక సంపూర్ణ బోధతో జవాబిచ్చాడు. ఆ కథను జ్ఞానులైన పక్షులు {jaimini|జైమినికి} చెబుతాయి:"],
   ["sglink", "Jaimini: What the Birds Answered", "జైమిని: పక్షులు ఇచ్చిన జవాబులు", "jm-9"],
   ["p", "Both stories carry the same quiet warning: the person everyone calls slow may be the wisest one in the room. And both show a sage choosing to look foolish so that he can stay free.", "రెండు కథలూ ఒకే నిశ్శబ్ద హెచ్చరిక ఇస్తాయి: అందరూ మందుడని పిలిచే మనిషే అక్కడ అందరికంటే జ్ఞాని కావచ్చు. స్వేచ్ఛగా ఉండటానికి మూర్ఖుడిలా కనిపించడాన్ని ఎంచుకున్న మునిని రెండూ చూపిస్తాయి."]
  ],
  [
   ["h", "In Telugu homes and beyond", "తెలుగు ఇళ్ళలో, ఇంకా బయటా"],
   ["p", "Telugu readers know this story from the Āndhra Mahābhāgavatamu, the great Telugu Bhāgavatam begun by Bammera Pōtana; the fifth book, in which it is told, is traditionally credited to the poet Bopparāju Gaṅgayya.", "తెలుగు పాఠకులకు ఈ కథ బమ్మెర పోతన మొదలుపెట్టిన ఆంధ్ర మహాభాగవతం ద్వారా తెలుసు; ఈ కథ ఉన్న ఐదవ స్కంధాన్ని సంప్రదాయం బొప్పరాజు గంగయ్య కవికి ఆపాదిస్తుంది."],
   ["p", "Jains, too, remember a Bharata, son of {rishabha|Ṛṣabha}, as the first cakravartin, the world-emperor of their tradition, who renounced in the end; their account of his life is their own and differs from the Purāṇas. And every time someone says “Bhārata” for this land, one of the two kings named Bharata is being remembered.", "జైనులు కూడా {rishabha|ఋషభుని} కొడుకు భరతుని తమ సంప్రదాయంలో మొదటి చక్రవర్తిగా, చివరికి సర్వసంగ పరిత్యాగం చేసినవాడిగా గుర్తుంచుకుంటారు; వాళ్ళ కథనం వాళ్ళదే, పురాణాలకు భిన్నమైనది. ఈ దేశాన్ని “భారతం” అన్న ప్రతిసారీ భరతుడనే ఇద్దరు రాజులలో ఒకరిని తలచుకుంటున్నాం."],
   ["h", "The lessons of three lives", "మూడు జన్మల పాఠాలు"],
   ["p", "As a king, Bharata shows that one can rule well and still keep the heart free. As a sage with a fawn, he shows that even kindness can turn into a chain, and that the last thought is the one we have practised. As a deer, he shows that it is never too late to turn back. And as the “dull” brāhmaṇa, he shows that true knowledge can sit quietly under a palanquin pole, needing no title — and that a proud king can still learn, if he is willing to get down.", "రాజుగా భరతుడు చక్కగా పాలిస్తూనే మనసును స్వేచ్ఛగా ఉంచుకోవచ్చని చూపిస్తాడు. లేడిపిల్లతో మునిగా, దయ కూడా బంధంగా మారవచ్చని, చివరి తలపు మనం అలవాటు చేసుకున్నదేనని చూపిస్తాడు. లేడిగా, వెనక్కి తిరగడానికి ఎప్పుడూ ఆలస్యం కాదని చూపిస్తాడు. “మొద్దు” బ్రాహ్మణునిగా, నిజమైన జ్ఞానం ఏ బిరుదూ అక్కర్లేకుండా పల్లకీ కర్ర కింద నిశ్శబ్దంగా ఉండగలదని — గర్విష్ఠి రాజు కూడా కిందకు దిగడానికి సిద్ధపడితే నేర్చుకోగలడని చూపిస్తాడు."],
   ["src", "Bhāgavata Purāṇa, Book 5, chapter 14 (the closing praise of Bharata: the fly and Garuḍa; the merit of hearing his story) and chapter 15 (Sumati and the line of Bharata). Viṣṇu Purāṇa, Aṃśa 2, adhyāya 16 (the end of Bharata's teaching to the king of Sauvīra). Mārkaṇḍeya Purāṇa, the story of Sumati called Jaḍa. Āndhra Mahābhāgavatamu (Telugu), fifth book. Jain accounts of Bharata Cakravartin.", "భాగవత పురాణం, ఐదవ స్కంధం, 14వ అధ్యాయం (భరతుని ముగింపు ప్రశంస: ఈగ, గరుడుడు; ఆయన కథ విన్న ఫలం), 15వ అధ్యాయం (సుమతి, భరత వంశం). విష్ణు పురాణం, రెండవ అంశం, 16వ అధ్యాయం (సౌవీర రాజుకు భరతుని బోధ ముగింపు). మార్కండేయ పురాణం, జడుడనే సుమతి కథ. ఆంధ్ర మహాభాగవతం, పంచమ స్కంధం. భరత చక్రవర్తిపై జైన కథనాలు."]
  ]
 ],
 remember: [
  ["The Bhāgavata says no king can follow {jadabharata|Bharata's} path, as a fly cannot follow Garuḍa.", "గరుడుని ఈగ అనుసరించలేనట్టు {jadabharata|భరతుని} దారిని ఏ రాజూ అనుసరించలేడని భాగవతం చెబుతుంది."],
  ["The Mārkaṇḍeya Purāṇa's {sumati_jada|Sumati} is another sage who acted dull to stay free.", "మార్కండేయ పురాణంలోని {sumati_jada|సుమతి} కూడా స్వేచ్ఛ కోసం మొద్దులా ఉన్న జ్ఞాని."],
  ["Three lives, three lessons: rule with a free heart, guard your last thought, and never think it too late to turn back.", "మూడు జన్మలు, మూడు పాఠాలు: స్వేచ్ఛగల మనసుతో పాలించు, నీ చివరి తలపును కాపాడుకో, వెనక్కి తిరగడానికి ఆలస్యమైందని ఎప్పుడూ అనుకోకు."]
 ],
 think: ["Of Bharata's three lives — king, deer, “dull” brāhmaṇa — which one teaches you the most, and why?", "భరతుని మూడు జన్మలలో — రాజు, లేడి, “మొద్దు” బ్రాహ్మణుడు — మీకు ఏది ఎక్కువ నేర్పుతుంది? ఎందుకు?"]
}
]);
